local g = {id="gnome-mage",name="Gnome Mage",class="MAGE",race="Gnome",abilityWord="Spell",abilitiesWord="spells",chapters={{name="Coldridge Valley",first=1,last=8,lo=1,hi=6},{name="Kharanos",first=9,last=17,lo=6,hi=11},{name="Ironforge",first=18,last=20,lo=10,hi=13},{name="Loch Modan",first=21,last=30,lo=11,hi=18},{name="Level 20 training",first=31,last=33,lo=20,hi=20},{name="Wetlands",first=34,last=43,lo=20,hi=29},{name="Duskwood to Arathi",first=44,last=48,lo=28,hi=32},{name="Stranglethorn Vale",first=49,last=54,lo=33,hi=40},{name="Riverglades",first=55,last=61,lo=37,hi=45},{name="Tanaris & Feralas",first=62,last=70,lo=43,hi=50},{name="Un'Goro to 60",first=71,last=83,lo=49,hi=60}},spells={fireball={name="Fireball",lv=1,icon="spell_fire_flamebolt",text="Your first attack. From level 4 it moves to Shift+- and you only use it to pull enemies that are far away.",type="Spell"},frostbolt={name="Frostbolt",lv=4,icon="spell_frost_frostbolt02",text="Your main attack all the way to 60. Slows the enemy.",type="Spell"},fireblast={name="Fire Blast",lv=6,icon="spell_fire_fireball",text="Instant hit. Press whenever it's ready, or while moving.",type="Spell"},frostnova={name="Frost Nova",lv=10,icon="spell_frost_frostnova",text="Freezes every enemy next to you. Then step away.",type="Spell"},icelance={name="Ice Lance",lv=20,icon="spell_frost_frostblast",text="Triple damage on a frozen enemy. Press right after Frost Nova.",type="Talent"},polymorph={name="Polymorph",lv=8,icon="spell_nature_polymorph",text="Turns an extra enemy into a sheep for a while. Don't hit the sheep.",type="Spell"},shoot={name="Shoot (wand)",lv=10,icon="ability_shootwand",text="Free damage with your wand. Use it to finish enemies. Needs a wand equipped.",type="Item"},blink={name="Blink",lv=20,icon="spell_arcane_blink",text="Teleports you a short way forward. Your escape button.",type="Spell"},coneofcold={name="Cone of Cold",lv=26,icon="spell_frost_glacier",text="Hits and slows everything in front of you.",type="Spell"},iceblock={name="Ice Block",lv=29,icon="spell_frost_frost",text="Nothing can hurt you for a few seconds. Press it when you're about to die.",type="Talent"},eureka={name="Eureka!",lv=1,icon="inv_gnometoy",text="Gnome racial. For 8 sec your spells cost 10% less mana and hit 10% harder. 2 min cooldown.",type="Racial"},counterspell={name="Counterspell",lv=24,icon="spell_frost_iceshock",text="Stops an enemy's spell while they're casting it.",type="Spell"},arcanemissiles={name="Arcane Missiles",lv=8,icon="spell_nature_starfall",text="Channels a stream of arcane bolts. Costs more mana than Frostbolt, so as Frost you rarely need it. Handy against enemies that resist Frost.",type="Spell"},arcaneexplosion={name="Arcane Explosion",lv=14,icon="spell_nature_wispsplode",text="Hits every enemy around you. Costs a lot of mana. For groups of enemies.",type="Spell"},blizzard={name="Blizzard",lv=20,icon="spell_frost_icestorm",text="Ice rains on an area for a few seconds. For big groups of enemies.",type="Spell"},flamestrike={name="Flamestrike",lv=16,icon="spell_fire_selfdestruct",text="Burns an area. Good right after Frost Nova on a group.",type="Spell"},icebarrier={name="Ice Barrier",lv=40,icon="spell_ice_lament",text="A shield that soaks up damage and adds 15% Frost damage. Use before every fight.",type="Talent"},managem={name="Mana Agate",lv=28,icon="inv_misc_gem_emerald_01",text="Instantly gives you mana back in a fight. Made by Conjure Mana Agate. One charge, so conjure a new one after you use it.",type="Item"},managem2={name="Mana Jade",lv=38,icon="inv_misc_gem_emerald_02",text="Better mana gem. Made by Conjure Mana Jade.",type="Item"},managem3={name="Mana Citrine",lv=48,icon="inv_misc_gem_opal_01",text="Better mana gem. Made by Conjure Mana Citrine.",type="Item"},managem4={name="Mana Ruby",lv=58,icon="inv_misc_gem_ruby_01",text="Best mana gem. Made by Conjure Mana Ruby.",type="Item"},water1={name="Conjured Water",lv=4,icon="inv_drink_06",text="Drink it after a fight to refill mana. Made by Conjure Water.",type="Item"},water2={name="Conjured Fresh Water",lv=10,icon="inv_drink_07",text="Better water from Conjure Water (rank 2).",type="Item"},water3={name="Conjured Purified Water",lv=20,icon="inv_drink_milk_02",text="Better water from Conjure Water (rank 3).",type="Item"},water4={name="Conjured Spring Water",lv=30,icon="inv_drink_10",text="Better water from Conjure Water (rank 4).",type="Item"},water5={name="Conjured Mineral Water",lv=40,icon="inv_drink_09",text="Better water from Conjure Water (rank 5).",type="Item"},water6={name="Conjured Sparkling Water",lv=50,icon="inv_drink_11",text="Better water from Conjure Water (rank 6).",type="Item"},water7={name="Conjured Crystal Water",lv=60,icon="inv_drink_18",text="Best water from Conjure Water (rank 7). You learn that rank from the Dire Maul quest Arcane Refreshment, not from the trainer.",type="Item"},food1={name="Conjured Muffin",lv=6,icon="inv_misc_food_10",text="Eat it after a fight to refill health. Made by Conjure Food.",type="Item"},food2={name="Conjured Bread",lv=12,icon="inv_misc_food_09",text="Better food from Conjure Food (rank 2).",type="Item"},food3={name="Conjured Rye",lv=22,icon="inv_misc_food_12",text="Better food from Conjure Food (rank 3).",type="Item"},food4={name="Conjured Pumpernickel",lv=32,icon="inv_misc_food_08",text="Better food from Conjure Food (rank 4).",type="Item"},food5={name="Conjured Sourdough",lv=42,icon="inv_misc_food_11",text="Better food from Conjure Food (rank 5).",type="Item"},food6={name="Conjured Sweet Roll",lv=52,icon="inv_misc_food_33",text="Better food from Conjure Food (rank 6).",type="Item"},food7={name="Conjured Cinnamon Roll",lv=60,icon="inv_misc_food_73cinnamonroll",text="Best food from Conjure Food (rank 7).",type="Item"},evocation={name="Evocation",lv=20,icon="spell_nature_purge",text="Channels to refill a big chunk of mana. Use after a hard fight.",type="Spell"},escape={name="Escape Artist",lv=1,icon="ability_rogue_trip",text="Gnome racial. Breaks roots and slows on you.",type="Racial"},coldsnap={name="Cold Snap",lv=32,icon="spell_frost_wizardmark",text="Resets your Frost cooldowns, so you can use Ice Block or Frost Nova again.",type="Talent"},removecurse={name="Remove Lesser Curse",lv=18,icon="spell_nature_removecurse",text="Removes a curse from you or a party member.",type="Spell"},frostfire={name="Frostfire Bolt",lv=40,icon="ability_mage_frostfirebolt",text="A big hit plus damage over time. Optional for a Frost mage.",type="Spell"},manashield={name="Mana Shield",lv=20,icon="spell_shadow_detectlesserinvisibility",text="Damage takes your mana instead of your health. Emergency only.",type="Spell"},frostarmor={name="Frost Armor",lv=1,icon="spell_frost_frostarmor02",text="Armor buff that slows enemies who hit you. Keep it on.",type="Spell"},icearmor={name="Ice Armor",lv=30,icon="spell_frost_frostarmor02",text="Replaces Frost Armor. Stronger. Keep it on.",type="Spell"},magearmor={name="Mage Armor",lv=34,icon="spell_magearmor",text="Better mana regen. Swap to it for long dungeon fights.",type="Spell"},arcaneint={name="Arcane Intellect",lv=1,icon="spell_holy_magicalsentry",text="More mana. Keep it on yourself and cast it on party members.",type="Spell"},conjurewater={name="Conjure Water",lv=4,icon="inv_drink_06",text="Makes a stack of water. The water goes on Alt + 1.",type="Spell"},conjurefood={name="Conjure Food",lv=6,icon="inv_misc_food_10",text="Makes a stack of food. The food goes on Alt + 2.",type="Spell"},conjuregem={name="Conjure Mana Agate",lv=28,icon="inv_misc_gem_emerald_01",text="Makes a Mana Agate. The gem goes on Shift + 5. Recast after you use it.",type="Spell"},conjuregem2={name="Conjure Mana Jade",lv=38,icon="inv_misc_gem_emerald_02",text="Makes a Mana Jade. The gem goes on Shift + 5.",type="Spell"},conjuregem3={name="Conjure Mana Citrine",lv=48,icon="inv_misc_gem_opal_01",text="Makes a Mana Citrine. The gem goes on Shift + 5.",type="Spell"},conjuregem4={name="Conjure Mana Ruby",lv=58,icon="inv_misc_gem_ruby_01",text="Makes a Mana Ruby. The gem goes on Shift + 5.",type="Spell"},comprehend={name="Comprehend Scroll",lv=6,icon="inv_scroll_03",text="Reads the odd scrolls monsters drop. Free buffs.",type="Spell"},slowfall={name="Slow Fall",lv=12,icon="spell_magic_featherfall",text="You float down slowly. Saves you from falling damage.",type="Spell"},hearth={name="Hearthstone",lv=1,icon="inv_misc_rune_01",text="Takes you to the inn you set as home. 1 hour cooldown.",type="Item"},tp_if={name="Teleport: Ironforge",lv=20,icon="spell_arcane_teleportironforge",text="Takes you to Ironforge. Uses a Rune of Teleportation.",type="Spell"},tp_sw={name="Teleport: Stormwind",lv=20,icon="spell_arcane_teleportstormwind",text="Takes you to Stormwind. Uses a Rune of Teleportation.",type="Spell"},mount={name="Mechanostrider",lv=40,icon="ability_mount_mechastrider",text="Your gnome mount. Buy it at Steelgrill's Depot, Dun Morogh.",type="Item"}},bars={{id="main",title="Main bar",how="Keys 1 to =. Everything you press in a normal fight.",slots={{key="1",uses={{1,"fireball"},{4,"frostbolt"}}},{key="2",uses={{6,"fireblast"}}},{key="3",uses={{10,"frostnova"}}},{key="4",uses={{20,"icelance"}}},{key="5",uses={{8,"polymorph"}}},{key="6",uses={{10,"shoot"}}},{key="7",uses={{20,"blink"}}},{key="8",uses={{26,"coneofcold"}}},{key="9",uses={{29,"iceblock"}}},{key="0",uses={{1,"eureka"}}},{key="-",uses={{24,"counterspell"}}},{key="=",uses={{8,"arcanemissiles"}}}}},{id="shift",title="Bottom left bar",how="Shift + 1 to =. Group fights, emergencies and rarer spells.",slots={{key="S1",uses={{14,"arcaneexplosion"}}},{key="S2",uses={{20,"blizzard"}}},{key="S3",uses={{16,"flamestrike"}}},{key="S4",uses={{40,"icebarrier"}}},{key="S5",uses={{28,"managem"},{38,"managem2"},{48,"managem3"},{58,"managem4"}}},{key="S6",uses={{20,"evocation"}}},{key="S7",uses={{1,"escape"}}},{key="S8",uses={{32,"coldsnap"}}},{key="S9",uses={{18,"removecurse"}}},{key="S0",uses={{40,"frostfire"}}},{key="S-",uses={{4,"fireball"}}},{key="S=",uses={{20,"manashield"}}}}},{id="side",title="Right bar",how="Click these with the mouse between fights. No key needed.",slots={{uses={{1,"frostarmor"},{30,"icearmor"}}},{uses={{34,"magearmor"}}},{uses={{1,"arcaneint"}}},{uses={{4,"conjurewater"}}},{uses={{6,"conjurefood"}}},{uses={{28,"conjuregem"},{38,"conjuregem2"},{48,"conjuregem3"},{58,"conjuregem4"}}},{uses={{6,"comprehend"}}},{uses={{12,"slowfall"}}},{uses={{1,"hearth"}}},{uses={{20,"tp_if"}}},{uses={{20,"tp_sw"}}},{uses={{40,"mount"}}}}},{id="alt",title="Bottom right bar",how="Alt + 1 and Alt + 2. The water and food you conjure. Drink and eat after fights.",slots={{key="A1",uses={{4,"water1"},{10,"water2"},{20,"water3"},{30,"water4"},{40,"water5"},{50,"water6"},{60,"water7"}}},{key="A2",uses={{6,"food1"},{12,"food2"},{22,"food3"},{32,"food4"},{42,"food5"},{52,"food6"},{60,"food7"}}}}}},talents={{lv="10–11",lo=10,hi=11,name="Precision (Frost tab)",how="Click it 2 times (once per level)",why="Your spells miss less often."},{lv="12–14",lo=12,hi=14,name="Improved Frostbolt",how="3 times",why="Frostbolt casts faster."},{lv="15–17",lo=15,hi=17,name="Frostbite",how="3 times",why="Your slowing spells can freeze enemies by themselves."},{lv="18–19",lo=18,hi=19,name="Improved Frostbolt",how="2 more times (5 of 5)"},{lv="20",lo=20,hi=20,name="Ice Lance",how="Once",why="Triple damage to frozen enemies. Your best new trick."},{lv="21–24",lo=21,hi=24,name="Ice Shards",how="4 times",why="Your Frost critical hits do more damage."},{lv="25–27",lo=25,hi=27,name="Shatter",how="3 times",why="Many more critical hits on frozen enemies."},{lv="28",lo=28,hi=28,name="Ice Shards",how="Once more (5 of 5)"},{lv="29",lo=29,hi=29,name="Ice Block",how="Once",why="Your \"don't die\" button."},{lv="30–31",lo=30,hi=31,name="Fingers of Frost",how="2 times",why="Sometimes your next spell treats the enemy as frozen: cast Ice Lance."},{lv="32",lo=32,hi=32,name="Cold Snap",how="Once",why="Resets your Frost cooldowns, so you can Ice Block or Frost Nova again."},{lv="33–35",lo=33,hi=35,name="Improved Cone of Cold",how="3 times",why="Cone of Cold hits harder."},{lv="36–38",lo=36,hi=38,name="Frost Channeling",how="3 times",why="Frost spells cost less mana."},{lv="39",lo=39,hi=39,name="Improved Blizzard",how="Once",why="Blizzard slows the enemies in it."},{lv="40",lo=40,hi=40,name="Ice Barrier",how="Once",why="A damage-absorbing shield. Use it before every fight."},{lv="41",lo=41,hi=41,name="Precision",how="Once more (3 of 3)"},{lv="42–46",lo=42,hi=46,name="Winter's Chill",how="5 times",why="Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},{lv="47–48",lo=47,hi=48,name="Arctic Reach",how="2 times",why="Longer range for Frostbolt, Ice Lance and Blizzard."},{lv="49–50",lo=49,hi=50,name="Permafrost",how="2 times",why="Your slows last longer and are stronger."},{lv="51–52",lo=51,hi=52,name="Improved Blizzard",how="2 more times (3 of 3)"},{lv="53",lo=53,hi=53,name="Frost Warding",how="Once",why="Ice Armor gives more armor."},{lv="54–56",lo=54,hi=56,name="Arcane Resilience (Arcane tab)",how="3 times",why="Switch to the Arcane tab now. More armor from your Intellect."},{lv="57–58",lo=57,hi=58,name="Wand Specialization",how="2 times",why="Your wand hits harder."},{lv="59–60",lo=59,hi=60,name="Arcane Subtlety",how="2 times",why="Enemies resist your spells less. That's all 51 points."}},words={{label="Action bar",text="The row of buttons at the bottom of your screen. Each button has a key: 1 uses the first button, 2 the second, and so on."},{label="Auction house",text="Where players buy and sell items. In Ironforge it's near the bank."},{label="Buff",text="A good effect on you, like Frost Armor. Its icon shows at the top right of your screen."},{label="Cooldown",text="Waiting time before you can use an ability again. The button shows a clock-style sweep."},{label="Critical",text="A critical hit (\"crit\") does about double damage. Its number pops up bigger."},{label="Dungeon",text="A private area for a group of 5 players, with bosses and better loot."},{label="Elite",text="A much stronger enemy. Its portrait has a golden dragon border. Skip these alone."},{label="Elites",text="Much stronger enemies with a golden dragon border on their portrait. Skip them alone.",hide=true},{label="Escort",text="A quest where you walk with an NPC and keep them alive until they're safe. Stay close and don't run ahead."},{label="Flight path",text="Talk to a flight master (the person with a gryphon) once to unlock that place. Then you can fly between any places you've unlocked."},{label="Frozen",text="Can't move. Frost Nova and Frostbite freeze enemies. Ice Lance does triple damage to frozen enemies."},{label="Graveyard",text="Where you appear as a ghost when you die. Run back to your body and click Resurrect."},{label="Hearthstone",text="A stone in your bag that teleports you to the inn you set as home. Usable once an hour."},{label="Humanoid",text="Enemies shaped like people: humans, trolls, furbolgs, gnolls and so on. They often drop cloth and coins."},{label="Inn",text="Every town's inn has an innkeeper. Make it your home for your Hearthstone, and log out there for bonus XP."},{label="Legacy",text="A Forever system: you earn points across your whole account and spend them on bonuses. Press Y."},{label="NPC",text="A character run by the game, not by a player: quest givers, trainers, vendors, guards."},{label="Pull",text="Starting a fight with an enemy, usually by hitting it from a distance."},{label="PvP",text="Fighting other players. On PvP servers, the other faction can attack you in some zones."},{label="Quest log",text="Your list of quests. Press L. Click a quest to read what to do and where."},{label="Racial",text="An ability you get from your race, not your class."},{label="Rank",text="A stronger version of an ability you already have. Learn it at your trainer; it replaces the old one in your spellbook."},{label="Reagent vendor",text="A shop NPC who sells things your spells use up, like Runes of Teleportation."},{label="Respawn",text="Enemies come back a few minutes after you kill them, so don't rest too long in a camp you cleared."},{label="Rested XP",text="Bonus XP you build up while logged out in an inn or city. Your XP bar turns blue while you have it."},{label="Spellbook",text="Every ability you've learned. Press P, then drag an ability from it onto your action bar."},{label="Talent",text="One point per level from 10. You spend it in the talent window (N) to make yourself stronger."},{label="Tank",text="The group member (often a warrior) whose job is to make enemies attack them, not you."},{label="Trainer",text="An NPC who teaches you new spells for gold. Mages need one every 2 levels."},{label="Vendor",text="An NPC who sells things and buys your junk. While talking to one, right-click an item in your bags to sell it."},{label="XP",text="Experience points. Quests and kills give XP. Fill the bar at the bottom of your screen to reach the next level."},{label="Zone",text="A big area of the world with its own name, like Darkshore or Dun Morogh. Its name shows above your minimap."}},pages={barsIntro="Where every spell should go, level by level. The main bar has what you press in every fight, on keys you reach without looking. Rarer and emergency spells go on |cff7fd4ffShift|r + number. Things you only use between fights go on the right bar, to click with the mouse. Hover over or tap a button to see what it does.",barsSetup="|cffffd200How to set this up in game|r\n\n1.  Press |cff7fd4ffEsc|r > |cffffd200Interface|r > |cffffd200Action Bars|r. Turn on the |cffffd200Bottom Left Bar|r, the |cffffd200Bottom Right Bar|r and the |cffffd200Right Bar|r.\n2.  Press |cff7fd4ffEsc|r > |cffffd200Key Bindings|r. Find |cffffd200Bottom Left Action Button 1|r to |cffffd20012|r and set them to |cff7fd4ffShift|r + |cff7fd4ff1|r … |cff7fd4ffShift|r + |cff7fd4ff=|r. Then set |cffffd200Bottom Right Action Button 1|r and |cffffd2002|r to |cff7fd4ffAlt|r + |cff7fd4ff1|r and |cff7fd4ffAlt|r + |cff7fd4ff2|r.\n3.  Open your spellbook (|cff7fd4ffP|r) and drag each spell to its place. Water, food and mana gems are items: drag them from your bags (|cff7fd4ffB|r) instead.\n4.  Turn on |cffffd200Lock Action Bars|r in the same Action Bars menu so you can't drag spells off by accident.",play="|cffffd200Quests|r\n\n•  A yellow |cffffff00!|r over someone's head means they have a quest for you. Click them and press Accept.\n•  A yellow |cffffff00?|r means you can hand in a finished quest there.\n•  Press |cff7fd4ffL|r to see your quests. Each one says what to do and where.\n•  Most of your XP comes from quests, so do every one you find.\n\n|cffffd200Fighting|r\n\n•  Click an enemy to target it, stand still, and press your attack key.\n•  Fight one enemy at a time. Mages hit hard but break easily.\n•  Enemy level colours: |cff9d9d9dgrey|r gives no XP, |cff1eff00green|r is easy, |cffffff00yellow|r is a fair fight, |cffff8000orange|r is hard and |cffff2020red|r means run.\n•  A golden dragon border on the portrait means |cffffd200elite|r. Don't fight those alone.\n\n|cffffd200After every fight|r\n\n•  Health low? Eat (|cff7fd4ffAlt|r + |cff7fd4ff2|r). Mana low? Drink (|cff7fd4ffAlt|r + |cff7fd4ff1|r). You sit down by yourself while eating or drinking. Don't move until the bars are full.\n•  You make your own food and water with Conjure Food and Conjure Water.\n\n|cffffd200Getting stronger|r\n\n•  |cffffd200Every 2 levels|r, visit a mage trainer and learn everything you can afford.\n•  |cffffd200Every level from 10|r, press |cff7fd4ffN|r and spend a talent point. See the |cffffd200Talents|r tab.\n•  New spells go into your spellbook (|cff7fd4ffP|r). The |cffffd200Action Bars|r tab shows where to put them.\n\n|cffffd200Gear: is this item better?|r\n\nThe colour of an item's name tells you how good it is:\n|cff9d9d9dGrey|r Poor: sell it\n|cffffffffWhite|r Common: basic\n|cff1eff00Green|r Uncommon: a good upgrade\n|cff0070ddBlue|r Rare: great, often from dungeons\n|cffa335eePurple|r Epic: the best, from raids\n|cff9a9a9aYou're wearing:|r |cffffd200Simple Robe|r, Chest · Cloth, 20 Armor\n|cff9a9a9avs|r\n|cff9a9a9aYou just found:|r |cffffd200Robe of the Owl|r, Chest · Cloth, 24 Armor, |cff1eff00+5 Intellect|r, |cff1eff00+4 Spirit|r\n\nBetter: it has |cffffd200Intellect|r, the stat mages want most. Put it on.\n•  |cffffd200What you can wear:|r |cffffd200cloth|r only. Mages can't wear leather, mail or plate.\n•  |cffffd200Stats to look for:|r |cffffd200Intellect|r first (more mana, more critical hits), then |cffffd200Stamina|r (more health) and |cffffd200Spirit|r (mana comes back faster). Later, |cffffd200+spell damage|r and |cffffd200+Frost damage|r are great too. Skip Strength and Agility.\n•  |cffffd200Name endings:|r green items often end in a word that tells you their stats. |cffffd200of the Owl|r (Intellect + Spirit) and |cffffd200of the Eagle|r (Stamina + Intellect) are great for you. |cffffd200of the Monkey|r and |cffffd200of the Tiger|r are for fighters.\n•  |cffffd200Weapons:|r a |cffffd200staff|r, or a dagger with an off-hand item. Your |cffffd200wand|r matters most: look at its |cffffd200damage per second|r number, higher is better.\n•  |cffffd200How to compare:|r point at the new item and hold |cff7fd4ffShift|r. The game shows what you're wearing right next to it. Right-click an item in your bags to put it on.\n•  |cffffd200Easy mode:|r the |cffffd200Pawn|r addon (see |cffffd200Addons|r (on the website)) puts a green arrow on items that are an upgrade for you.\n•  |cffffd200Quest rewards:|r when you can pick one, take the one with Intellect. If none fits, take the one that sells for the most.\n\n|cffffd200Getting around|r\n\n•  Talk to the innkeeper in each new town and choose \"Make this inn your home\". Your Hearthstone then brings you back there.\n•  Talk to every flight master (the person with a gryphon) you pass, so you can fly there later.\n•  If you die, you appear as a ghost at a graveyard. Run back to your body and click \"Resurrect\".\n•  Log out inside an inn to get bonus XP next time.\n\n|cffffd200Addons|r\n\nAddons are free extras that improve the game's interface. You don't need any, but a few make leveling much easier. The |cffffd200Addons page|r (on the website) lists which ones to get (must-have, recommended, optional, and a separate list for dungeons) and how to install them.\n\n|cffffd200Waypoint arrow:|r with the |cffffd200TomTom|r addon, click a pin on any Quest Guide map and press |cffffd200Copy /way|r. In game, press |cff7fd4ffEnter|r, paste with |cff7fd4ffCtrl|r + |cff7fd4ffV|r and press |cff7fd4ffEnter|r again. An arrow points the way. |cffffd200/way reset all|r clears it.\n\n|cffffd200Useful keys|r\n\n|cff7fd4ffL|r  Quest log      |cff7fd4ffM|r  Map\n|cff7fd4ffP|r  Spellbook      |cff7fd4ffN|r  Talents\n|cff7fd4ffC|r  Your character      |cff7fd4ffB|r  Bags\n|cff7fd4ffX|r  Sit down      |cff7fd4ffY|r  Legacy (from about level 25)\n\n|cffffd200The one combo to learn|r\n\n1.  Frostbolt the enemy from far away, and keep casting while it walks to you.\n2.  When it reaches you: |cffffd200Frost Nova|r. It freezes in place.\n3.  Walk a few steps away.\n4.  |cffffd200Ice Lance|r (from level 20) or Fire Blast.\n5.  Back to Frostbolt until it's dead.",talentsIntro="From level 10 you get one talent point each level. Press |cff7fd4ffN|r, pick the |cffffd200Frost|r tab, and click the talent from this list. If one is greyed out, take the next one and come back.",talentsHint="Made a mistake? Any mage trainer can reset your talents for a little gold."}}
g.steps = {
  {kind="start",chapter=1,lv="1",lo=1,hi=1,place="Coldridge Valley",title="Before you do anything",todo={"Press |cff7fd4ffP|r to open your |cffe2c6ff|Hwfw:26|hspellbook|h|r.","Drag each spell from your |cffe2c6ff|Hwfw:26|hspellbook|h|r to the key shown in the |cffffd200|cffe2c6ff|Hwfw:1|hAction bar|h|r|r box below. If the extra bars aren't showing yet, see |cffffd200How to set this up in game|r on the Action Bars tab.","Click each one to cast it on yourself. These are your buffs. Recast them whenever their icons disappear from the top right of your screen."},done="every spell in the |cffffd200|cffe2c6ff|Hwfw:1|hAction bar|h|r|r box below is on its key and your buffs are on.",tip="Fireball is already on key |cff7fd4ff1|r. That's your attack for now.",bars={head="Action bar",rows={{id="fireball",where="Key |cff7fd4ff1|r |cff9a9a9amain bar|r"},{id="frostarmor",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r"},{id="arcaneint",where="Right bar, button |cffffd2003|r |cff9a9a9acounting from the top|r"},{id="eureka",where="Key |cff7fd4ff0|r |cff9a9a9amain bar|r"},{id="escape",where="|cff7fd4ffShift|r + |cff7fd4ff7|r |cff9a9a9abottom left bar|r"},{id="hearth",where="Right bar, button |cffffd2009|r |cff9a9a9acounting from the top|r"}},notes={"First time? Turn on the extra bars first: |cffffd200Action Bars tab|r > How to set this up in game.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Dun Morogh",x=29.9,y=71.2,label="You start here, outside Anvilmar"}},quests={"Action bar","How to set this up in game"}},
  {kind="quest",chapter=1,lv="1",lo=1,hi=1,place="Coldridge Valley",title="Your first quest",todo={"Talk to |cffffd200Sten Stoutarm|r, the dwarf right in front of you. He has a yellow |cffffd200!|r over his head. Accept |cffffd200Dwarven Outfitters|r.","Walk south-west and kill ragged wolves until you have |cffffd2008 Tough Wolf Meat|r.","Go back to Sten. He now has a yellow |cffffd200?|r. Talk to him to turn in the quest, then take your mage quest, |cffffd200Glyphic Memorandum|r."},done="you've handed in |cffffd200Dwarven Outfitters|r and have |cffffd200Glyphic Memorandum|r in your |cffe2c6ff|Hwfw:20|hquest log|h|r.",tip="How to fight: click a wolf to target it, then press |cff7fd4ff1|r while standing still. Start casting before it reaches you.",pins={{zone="Dun Morogh",x=29.9,y=71.2,label="Sten Stoutarm"},{zone="Dun Morogh",x=26.5,y=75.5,label="Wolves"}},quests={"Sten Stoutarm","Dwarven Outfitters","Glyphic Memorandum"}},
  {kind="train",chapter=1,lv="1–3",lo=1,hi=3,place="Coldridge Valley",title="Meet your trainer and the troggs",todo={"Take |cffffd200Glyphic Memorandum|r to |cffffd200Marryk Nurribit|r, the mage |cffe2c6ff|Hwfw:29|htrainer|h|r inside Anvilmar, the building behind Sten.","Take |cffffd200A New Threat|r from |cffffd200Balir Frosthammer|r next to Sten: kill |cffffd2006 Rockjaw Troggs|r and |cffffd2006 Burly Rockjaw Troggs|r in the hills south of the wolves. Hand it back to Balir.","Take |cffffd200Coldridge Valley Mail Delivery|r from Sten for the next step. In Anvilmar, the gnome |cffffd200Felix Whindlebolt|r gives |cffffd200A Refugee's Quandary|r: his lost box, chest and bucket are in the troll camps in the south-west."},done="Marryk has the |cffffd200Glyphic Memorandum|r and you've handed in |cffffd200A New Threat|r.",stuck="Fight the troggs south of Anvilmar until you're level 3.",tip="After every fight, if your health or mana is low, sit and eat or drink before the next one. It saves you from dying.",pins={{zone="Dun Morogh",x=28.7,y=66.4,label="Marryk Nurribit (inside Anvilmar)"},{zone="Dun Morogh",x=29.9,y=71.2,label="Sten and Balir"},{zone="Dun Morogh",x=28,y=79,label="Troggs"}},quests={"Glyphic Memorandum","Marryk Nurribit","A New Threat","Balir Frosthammer","Coldridge Valley Mail Delivery","Felix Whindlebolt","A Refugee's Quandary"}},
  {kind="quest",chapter=1,lv="3–5",lo=3,hi=5,place="Coldridge Valley",title="Deliver the mail",todo={"Walk west from Anvilmar to |cffffd200Talin Keeneye|r and give him the mail. Take |cffffd200The Boar Hunter|r (kill small crag boars around his camp) and the next mail delivery.","Take the mail to |cffffd200Grelin Whitebeard|r's camp to the south. Take |cffffd200The Troll Cave|r: kill |cffffd20014 Frostmane troll whelps|r in and around the cave.","Then |cffffd200The Stolen Journal|r: go into the cave, keep to the left, kill |cffffd200Grik'nir the Cold|r and loot the journal. Hand both to Grelin.","Pick up Felix's |cffffd200box|r, |cffffd200chest|r and |cffffd200bucket of bolts|r in the troll camps here. At Grelin's camp, |cffffd200Nori Pridedrift|r gives |cffffd200Scalding Mornbrew Delivery|r, and Grelin gives |cffffd200Senir's Observations|r."},done="Grik'nir is dead, |cffffd200The Stolen Journal|r is handed in, and |cffffd200Scalding Mornbrew Delivery|r is in your |cffe2c6ff|Hwfw:20|hquest log|h|r.",stuck="Fight the young trolls in the cave until you're level 5.",tip="In caves, enemies stand close together. Fight them one at a time: target the closest one and step back so you don't |cffe2c6ff|Hwfw:18|hpull|h|r its friends.",pins={{zone="Dun Morogh",x=22.6,y=71.4,label="Talin Keeneye"},{zone="Dun Morogh",x=25.1,y=75.7,label="Grelin Whitebeard's camp"},{zone="Dun Morogh",x=26.8,y=79.2,label="Troll cave"},{zone="Dun Morogh",x=22.8,y=79.9,label="Felix's things (troll camps)"}},quests={"Talin Keeneye","The Boar Hunter","Grelin Whitebeard","The Troll Cave","The Stolen Journal","Grik'nir the Cold","box","chest","bucket of bolts","Nori Pridedrift","Scalding Mornbrew Delivery","Senir's Observations"}},
  {kind="train",chapter=1,lv="4",lo=4,hi=4,place="Marryk Nurribit (trainer)",title="Level 4: your main spell",todo={"Go back to Marryk and learn |cffffd200Frostbolt|r and |cffffd200Conjure Water|r.","Put Frostbolt on key |cff7fd4ff1|r and move Fireball to |cff7fd4ffShift|r + |cff7fd4ff-|r. Frostbolt slows the enemy, so it takes longer to reach you.","Cast Conjure Water a few times. It makes |cffffd200Conjured Water|r in your bags. Drag that water onto |cff7fd4ffAlt|r + |cff7fd4ff1|r and drink it (press |cff7fd4ffAlt|r + |cff7fd4ff1|r) whenever your mana is low."},done="Frostbolt is on |cff7fd4ff1|r, Fireball on |cff7fd4ffShift|r + |cff7fd4ff-|r, and your water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r.",bars={head="Action bar",rows={{id="frostbolt",where="Key |cff7fd4ff1|r |cff9a9a9amain bar|r",replaces="Fireball"},{id="fireball",where="|cff7fd4ffShift|r + |cff7fd4ff-|r |cff9a9a9abottom left bar|r"},{id="conjurewater",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r"},{id="water1",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Dun Morogh",x=28.7,y=66.4,label="Marryk Nurribit (mage trainer)"}},quests={"Frostbolt","Conjure Water","Conjured Water"}},
  {kind="quest",chapter=1,lv="5",lo=5,hi=5,place="Anvilmar",title="Hot mornbrew and Felix's things",todo={"|cffffd200Scalding Mornbrew Delivery|r: run the hot mornbrew straight to |cffffd200Durnan Furcutter|r in Anvilmar before it goes cold. Don't stop to fight on the way.","Durnan gives |cffffd200Bring Back the Mug|r: take the empty mug back to Nori at Grelin's camp.","Give Felix his three things in Anvilmar. If |cffffd200Grund Drokda|r at Anvilmar offers |cffffd200Grund and Gozwin|r, do it too: the reward is a 6-slot bag. Right-click a new bag to put it in a free bag slot."},done="you've handed in |cffffd200Scalding Mornbrew Delivery|r, |cffffd200Bring Back the Mug|r and |cffffd200A Refugee's Quandary|r.",pins={{zone="Dun Morogh",x=28.7,y=66.4,label="Anvilmar"},{zone="Dun Morogh",x=25.1,y=75.7,label="Nori Pridedrift (Grelin's camp)"}},quests={"Scalding Mornbrew Delivery","Durnan Furcutter","Bring Back the Mug","Grund Drokda","Grund and Gozwin"}},
  {kind="train",chapter=1,lv="6",lo=6,hi=6,place="Marryk Nurribit (trainer)",title="Level 6: train again",todo={"Learn |cffffd200Fire Blast|r, |cffffd200Conjure Food|r and |cffffd200Comprehend Scroll|r.","Cast Conjure Food. It makes |cffffd200Conjured Muffins|r in your bags. Drag them onto |cff7fd4ffAlt|r + |cff7fd4ff2|r and eat (press |cff7fd4ffAlt|r + |cff7fd4ff2|r) whenever your health is low.","Put Fire Blast on key |cff7fd4ff2|r. It hits instantly. Use it whenever it's ready.","Visit the junior gathering trainers nearby and take the free gathering book."},done="Fire Blast is on |cff7fd4ff2|r and your muffins are on |cff7fd4ffAlt|r + |cff7fd4ff2|r.",tip="Comprehend Scroll is a mage-only skill in Forever. Monsters sometimes drop odd scrolls; use it on them to get free buffs and small spells.",bars={head="Action bar",rows={{id="fireblast",where="Key |cff7fd4ff2|r |cff9a9a9amain bar|r"},{id="conjurefood",where="Right bar, button |cffffd2005|r |cff9a9a9acounting from the top|r"},{id="comprehend",where="Right bar, button |cffffd2007|r |cff9a9a9acounting from the top|r"},{id="food1",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Dun Morogh",x=28.7,y=66.4,label="Marryk Nurribit (mage trainer)"}},quests={"Fire Blast","Conjure Food","Comprehend Scroll","Conjured Muffins"}},
  {kind="travel",chapter=1,lv="6",lo=6,hi=6,place="Coldridge Pass",title="Leave the valley",todo={"At the tunnel out of the valley (Coldridge Pass), hand |cffffd200Senir's Observations|r to |cffffd200Mountaineer Thalos|r and do the second part he gives you.","Take |cffffd200Supplies to Tannok|r from |cffffd200Hands Springsprocket|r.","Walk through the tunnel to the town of |cffffd200Kharanos|r."},done="you're in Kharanos with |cffffd200Supplies to Tannok|r in your |cffe2c6ff|Hwfw:20|hquest log|h|r.",pins={{zone="Dun Morogh",x=33.9,y=72.2,label="Coldridge Pass: Thalos and Hands Springsprocket"},{zone="Dun Morogh",x=46.7,y=53,label="Kharanos"}},quests={"Senir's Observations","Mountaineer Thalos","Supplies to Tannok","Hands Springsprocket","Kharanos"}},
  {kind="home",chapter=2,lv="6",lo=6,hi=6,place="Kharanos",title="Make Kharanos your home",todo={"Find the innkeeper in the Thunderbrew Distillery (the big |cffe2c6ff|Hwfw:15|hinn|h|r) and choose |cffffd200Make this inn your home|r.","Your |cffffd200|cffe2c6ff|Hwfw:13|hHearthstone|h|r|r (in your bag) now teleports you back here. It has a 1 hour |cffe2c6ff|Hwfw:4|hcooldown|h|r.","Hand |cffffd200Supplies to Tannok|r to |cffffd200Tannok Frosthammer|r in the |cffe2c6ff|Hwfw:15|hinn|h|r."},done="your |cffe2c6ff|Hwfw:13|hHearthstone|h|r says |cffffd200Kharanos|r when you hover over it, and |cffffd200Supplies to Tannok|r is handed in.",tip="Always log out inside an |cffe2c6ff|Hwfw:15|hinn|h|r. You'll get bonus |cffe2c6ff|Hwfw:31|hXP|h|r (called |cffe2c6ff|Hwfw:25|hrested XP|h|r) when you come back.",pins={{zone="Dun Morogh",x=47.3,y=52.4,label="Thunderbrew Distillery (inn)"}},quests={"Make this inn your home","Hearthstone","Supplies to Tannok","Tannok Frosthammer"}},
  {kind="quest",chapter=2,lv="6",lo=6,hi=6,place="Kharanos",title="Learn Cooking",todo={"Find the cooking |cffe2c6ff|Hwfw:29|htrainer|h|r in Kharanos and learn Cooking.","Do |cffffd200Beer Basted Boar Ribs|r from |cffffd200Ragnar Thunderbrew|r by the |cffe2c6ff|Hwfw:15|hinn|h|r door: kill crag boars on the roads for |cffffd200Crag Boar Ribs|r, buy the |cffffd200Rhapsody Malt|r in the inn, and cook. It teaches you a recipe.","Cooked food gives the |cffffd200Well Fed|r |cffe2c6ff|Hwfw:3|hbuff|h|r: 5% more |cffe2c6ff|Hwfw:31|hXP|h|r from kills."},done="you've learned Cooking and handed in |cffffd200Beer Basted Boar Ribs|r.",pins={{zone="Dun Morogh",x=47.3,y=52.4,label="Thunderbrew Distillery"}},quests={"Beer Basted Boar Ribs","Ragnar Thunderbrew","Crag Boar Ribs","Rhapsody Malt","Well Fed"}},
  {kind="quest",chapter=2,lv="6–7",lo=6,hi=7,place="Kharanos",title="Grab every quest in town",todo={"At |cffffd200Steelgrill's Depot|r, the gnome hangar just north-east of town, take |cffffd200Stocking Jetsteam|r (Pilot Bellowfiz: |cffffd2004 Chunks of Boar Meat|r and |cffffd2002 Thick Bear Furs|r), |cffffd200The Grizzled Den|r (Pilot Stonegear: |cffffd200Wendigo Manes|r from the wendigos in the cave west of town) and |cffffd200Ammo for Rumbleshot|r (Loslor Rudge).","|cffffd200Ammo for Rumbleshot|r: pick up the ammo crate at the wrecked camp just south of Kharanos and take it to |cffffd200Hegnar Rumbleshot|r, further south along the road.","In town, also take |cffffd200Frostmane Hold|r from |cffffd200Senir Whitebeard|r and |cffffd200Operation Recombobulation|r from |cffffd200Razzle Sprysprocket|r.","Hand the Depot quests back at the Depot. Press |cff7fd4ffL|r to open your |cffe2c6ff|Hwfw:20|hquest log|h|r: each quest says how many you need."},done="you've handed in |cffffd200Stocking Jetsteam|r, |cffffd200The Grizzled Den|r and |cffffd200Ammo for Rumbleshot|r.",stuck="Fight the boars, bears and wendigos near Kharanos until you're level 7.",pins={{zone="Dun Morogh",x=46.7,y=53,label="Kharanos"},{zone="Dun Morogh",x=49.4,y=48.4,label="Steelgrill's Depot"},{zone="Dun Morogh",x=42.5,y=53,label="The Grizzled Den"},{zone="Dun Morogh",x=44,y=56,label="Wrecked camp (ammo crate)"},{zone="Dun Morogh",x=40.6,y=65.1,label="Hegnar Rumbleshot"}},quests={"Steelgrill's Depot","Stocking Jetsteam","The Grizzled Den","Wendigo Manes","Ammo for Rumbleshot","Hegnar Rumbleshot","Frostmane Hold","Senir Whitebeard","Operation Recombobulation","Razzle Sprysprocket"}},
  {kind="quest",chapter=2,lv="7–8",lo=7,hi=8,place="West of Kharanos",title="Gnome quest: fix the machines",todo={"For |cffffd200Operation Recombobulation|r, go west toward Gnomeregan and kill the Leper Gnomes outside it for |cffffd200Gyromechanic Gears|r and |cffffd200Restabilization Cogs|r. Don't go into Gnomeregan itself.","Bring them back to Razzle Sprysprocket in Kharanos."},done="Razzle has his gears and cogs.",stuck="Fight the Leper Gnomes west of Kharanos until you're level 8.",pins={{zone="Dun Morogh",x=45.9,y=49.4,label="Razzle Sprysprocket"},{zone="Dun Morogh",x=25.5,y=41.5,label="Leper Gnomes"}},quests={"Operation Recombobulation","Gyromechanic Gears","Restabilization Cogs"}},
  {kind="train",chapter=2,lv="8",lo=8,hi=8,place="Magis Sparkmantle (trainer, Kharanos)",title="Level 8: Polymorph",todo={"Kharanos has its own mage |cffe2c6ff|Hwfw:29|htrainer|h|r, |cffffd200Magis Sparkmantle|r. Learn |cffffd200Polymorph|r and |cffffd200Arcane Missiles|r.","Put Polymorph on key |cff7fd4ff5|r and Arcane Missiles on key |cff7fd4ff=|r."},done="Polymorph is on |cff7fd4ff5|r and Arcane Missiles on |cff7fd4ff=|r.",tip="If two enemies attack you, cast Polymorph on one of them. It turns into a sheep and can't fight for a while. Kill the other one, then deal with the sheep. Don't hit the sheep, or it wakes up.",bars={head="Action bar",rows={{id="polymorph",where="Key |cff7fd4ff5|r |cff9a9a9amain bar|r"},{id="arcanemissiles",where="Key |cff7fd4ff=|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Dun Morogh",x=47.3,y=52.4,label="Magis Sparkmantle (Kharanos)"}},quests={"Magis Sparkmantle","Polymorph","Arcane Missiles"}},
  {kind="quest",chapter=2,lv="8–10",lo=8,hi=10,place="Brewnall Village and the troll camps",title="Trolls, stout and the beer feud",todo={"|cffffd200Frostmane Hold|r: go to the troll cave in the south-west, walk in far enough to get the |cffffd200Explore|r message, and kill |cffffd2005 Frostmane Headhunters|r. Hand it back to Senir in Kharanos.","At |cffffd200Brewnall Village|r by the |cffe2c6ff|Hwfw:11|hfrozen|h|r lake, |cffffd200Rejold Barleybrew|r gives the stout quests: |cffffd200The Perfect Stout|r and then |cffffd200Shimmer Stout|r. Climb the path up to |cffffd200Shimmer Ridge|r, kill the trolls and loot the baskets for |cffffd200Shimmerweed|r. He also gives |cffffd200A Favor for Evershine|r (bears, boars and leopards).","|cffffd200Marleth Barleybrew|r, also in Brewnall, gives |cffffd200Bitter Rivals|r. In the Kharanos |cffe2c6ff|Hwfw:15|hinn|h|r, buy a |cffffd200Thunder Ale|r from the innkeeper and give it to |cffffd200Jarven Thunderbrew|r (|cffffd200Distracting Jarven|r), then click the unguarded barrel behind him and take |cffffd200Return to Marleth|r back to Brewnall.","If you see a new quest about |cffffd200snow leopards|r or |cffffd200wendigos|r, take it too. Forever added a new chain around this level."},done="you've handed in |cffffd200Frostmane Hold|r, |cffffd200Shimmer Stout|r, |cffffd200Return to Marleth|r and |cffffd200A Favor for Evershine|r, and you're level 10.",stuck="Fight the Frostmane trolls at Shimmer Ridge until you are.",tip="Trolls come in groups. |cffe2c6ff|Hwfw:18|hPull|h|r one at a time with Frostbolt from far away.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=30.5,y=45.5,label="Brewnall Village (Rejold and Marleth)"},{zone="Dun Morogh",x=37,y=42,label="Shimmer Ridge (path up at the camp)"},{zone="Dun Morogh",x=25,y=51,label="Frostmane Hold"},{zone="Dun Morogh",x=47.3,y=52.4,label="Kharanos inn (Jarven)"}},quests={"Frostmane Hold","Explore","Brewnall Village","Rejold Barleybrew","The Perfect Stout","Shimmer Stout","Shimmer Ridge","Shimmerweed","A Favor for Evershine","Marleth Barleybrew","Bitter Rivals","Thunder Ale","Jarven Thunderbrew","Distracting Jarven","Return to Marleth","snow leopards","wendigos"}},
  {kind="train",chapter=2,lv="10",lo=10,hi=10,place="Magis Sparkmantle (trainer, Kharanos)",title="Level 10: Frost Nova and your first talent",todo={"Learn |cffffd200Frost Nova|r and the new |cffe2c6ff|Hwfw:22|hrank|h|r of |cffffd200Conjure Water|r. Put Frost Nova on key |cff7fd4ff3|r and the new water on |cff7fd4ffAlt|r + |cff7fd4ff1|r.","Press |cff7fd4ffN|r to open talents. Click the |cffffd200Frost|r tab and put your point into |cffffd200Precision|r: your spells miss less often.","Magis also gives you |cffffd200Speak with Bink|r, a mage quest in Ironforge. Keep it for later."},done="Frost Nova is on |cff7fd4ff3|r, your new water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r, and your |cffe2c6ff|Hwfw:27|htalent|h|r point is in Precision.",tip="The combo to learn now: Frostbolt the enemy. When it reaches you, press Frost Nova. It freezes in place. Walk a few steps away and keep casting Frostbolt.",bars={head="Action bar",rows={{id="frostnova",where="Key |cff7fd4ff3|r |cff9a9a9amain bar|r"},{id="water2",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=47.3,y=52.4,label="Magis Sparkmantle (Kharanos)"}},quests={"Frost Nova","Conjure Water","Frost","Precision","Speak with Bink"}},
  {kind="quest",chapter=2,lv="10",lo=10,hi=10,place="Gol'Bolar Quarry (east)",title="The quarry",todo={"Follow the road east to Gol'Bolar Quarry.","Take |cffffd200Those Blasted Troggs!|r from Foreman Stonebrow (Rockjaw Skullthumpers in the quarry) and |cffffd200The Public Servant|r from Senator Mehr Stonehallow (Rockjaw Bonesnappers in the mine). Your |cffe2c6ff|Hwfw:20|hquest log|h|r says how many.","Talk to |cffffd200Earthseer Farsen|r and take |cffffd200Nip 'Em in the Bud|r: kill 10 Dark Iron Spies east of the quarry.","One spy drops a |cffffd200Dark Iron Map|r. Right-click it, bring it to Farsen and take |cffffd200Old Ironforge Incursion|r. That's a |cffe2c6ff|Hwfw:6|hdungeon|h|r quest for later."},done="you've handed in |cffffd200Those Blasted Troggs!|r, |cffffd200The Public Servant|r and |cffffd200Nip 'Em in the Bud|r.",stuck="Fight the troggs at the quarry until you're level 11.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=68.9,y=56,label="Gol'Bolar Quarry"},{zone="Dun Morogh",x=74,y=53,label="Dark Iron Spies"}},quests={"Those Blasted Troggs!","The Public Servant","Earthseer Farsen","Nip 'Em in the Bud","Dark Iron Map","Old Ironforge Incursion"}},
  {kind="quest",chapter=2,lv="10–11",lo=10,hi=11,place="Dun Morogh",title="Wrap up Dun Morogh",todo={"Turn in everything in Kharanos and Brewnall.","Skip |cffffd200Protecting the Herd|r. Its boss, Vagash, is an |cffffd200|cffe2c6ff|Hwfw:7|helite|h|r|r, too strong to fight alone.","On the road east, at the |cffffd200South Gate Outpost|r, |cffffd200Mountaineer Barleybrew|r gives |cffffd200Stout to Kadrell|r: carry the cask to Mountaineer Kadrell in Thelsamar, Loch Modan."},done="Kharanos and Brewnall have nothing left for you and |cffffd200Stout to Kadrell|r is in your log.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=46.7,y=53,label="Kharanos"},{zone="Dun Morogh",x=86,y=48,label="South Gate Outpost (Mountaineer Barleybrew)"}},quests={"Protecting the Herd","elite","South Gate Outpost","Mountaineer Barleybrew","Stout to Kadrell"}},
  {kind="travel",chapter=3,lv="10–11",lo=10,hi=11,place="Ironforge",title="Visit Ironforge",todo={"Follow the road north from Kharanos to the big gate of |cffffd200Ironforge|r.","Inside, find the gryphon master and talk to him to unlock the |cffffd200|cffe2c6ff|Hwfw:10|hflight path|h|r|r.","Find the Tailoring and Enchanting trainers and learn both. Tailoring lets you make your own clothes from the cloth enemies drop. Step-by-step leveling routes are on the |cffffd200Professions page|r (on the website)."},done="you've unlocked the Ironforge |cffe2c6ff|Hwfw:10|hflight path|h|r and learned Tailoring and Enchanting.",tip="Lost in Ironforge? Ask any guard. Click them and they'll mark the place on your map.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=53.5,y=34.9,label="Gates of Ironforge"},{zone="Ironforge",x=15,y=85,label="You come in here"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master"}},quests={"Ironforge","flight path"}},
  {kind="quest",chapter=3,lv="10–11",lo=10,hi=11,place="Ironforge, Mystic Ward",title="Mage quest: Bink",todo={"Go to the Mystic Ward and find |cffffd200Bink|r in the Hall of Mysteries. Turn in |cffffd200Speak with Bink|r.","She gives |cffffd200Mage-tastic Gizmonitor|r. Go west in Dun Morogh to the huts just north of Gnomeregan: the gizmonitor is in a small chest inside the hut on the right.","Lots of Leper Gnomes walk around there. Polymorph one if two come at you. |cffffd200Don't go inside Gnomeregan|r: everything there is much too strong for you.","Bring it back to Bink and choose your reward: the |cffffd200Ley Orb|r or the |cffffd200Ley Staff|r."},done="you've handed in |cffffd200Mage-tastic Gizmonitor|r to Bink and picked the Ley Orb or Ley Staff.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Bink (Hall of Mysteries)"},{zone="Dun Morogh",x=27,y=36,label="Hut north of Gnomeregan (chest)"}},quests={"Bink","Speak with Bink","Mage-tastic Gizmonitor","Don't go inside Gnomeregan","Ley Orb","Ley Staff"}},
  {kind="dungeon",chapter=3,lv="10–13",lo=10,hi=13,place="Ironforge",title="Get a wand and a dungeon quest",todo={"Buy a |cffffd200Lesser Magic Wand|r from the |cffe2c6ff|Hwfw:2|hauction house|h|r, or ask an enchanter to make you one. At level 13, upgrade to a |cffffd200Greater Magic Wand|r.","Put your wand's |cffffd200Shoot|r on key |cff7fd4ff6|r. Use it to finish enemies that are almost dead. It costs no mana.","Find |cffffd200Thom Filch|r near the bridge under the king's throne room and take |cffffd200Important Heirlooms|r. It's for the Hall of Thanes |cffe2c6ff|Hwfw:6|hdungeon|h|r later."},done="a wand is equipped, Shoot is on |cff7fd4ff6|r, and |cffffd200Important Heirlooms|r is in your log.",bars={head="Action bar · when you next visit the trainer",rows={{id="shoot",where="Key |cff7fd4ff6|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often.","Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster."},pins={{zone="Ironforge",x=25,y=74,label="Auction house"},{zone="Ironforge",x=39,y=55,label="Thom Filch (below the High Seat)"}},quests={"Lesser Magic Wand","Greater Magic Wand","Shoot","Thom Filch","Important Heirlooms"}},
  {kind="travel",chapter=4,lv="11",lo=11,hi=11,place="Road to Loch Modan",title="Move to Loch Modan",todo={"From Kharanos, follow the road east through the mountain tunnel into |cffffd200Loch Modan|r.","At the southern guard tower, take |cffffd200The Trogg Threat|r from |cffffd200Captain Rugelfuss|r (8 Trogg Stone Teeth) and |cffffd200In Defense of the King's Lands|r from |cffffd200Mountaineer Cobbleflint|r (10 Stonesplinter Troggs and 10 Stonesplinter Scouts).","Both are done in |cffffd200Stonesplinter Valley|r, south of Thelsamar: the troggs drop the teeth."},done="you have |cffffd200The Trogg Threat|r and |cffffd200In Defense of the King's Lands|r.",talents={"Level 10–11: |cffffd200Precision (Frost tab)|r, click it 2 times (once per level). Your spells miss less often."},pins={{zone="Dun Morogh",x=46.7,y=53,label="Kharanos"},{zone="Dun Morogh",x=87.5,y=50,label="Tunnel to Loch Modan"},{zone="Loch Modan",x=23.3,y=74,label="Southern guard tower"}},quests={"Loch Modan","The Trogg Threat","Captain Rugelfuss","In Defense of the King's Lands","Mountaineer Cobbleflint","Stonesplinter Valley"}},
  {kind="home",chapter=4,lv="12",lo=12,hi=12,place="Thelsamar",title="Your new home: Thelsamar",todo={"Follow the road to the town of |cffffd200Thelsamar|r.","Make the |cffe2c6ff|Hwfw:15|hinn|h|r your home. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r. Hand |cffffd200Stout to Kadrell|r to |cffffd200Mountaineer Kadrell|r.","Take every quest in town: |cffffd200Rat Catching|r and |cffffd200Mountaineer Stormpike's Task|r (Kadrell), |cffffd200Thelsamar Blood Sausages|r (Vidra Hearthstove) and |cffffd200Ironband's Excavation|r (Jern Hornhelm)."},done="Thelsamar is your home, the |cffe2c6ff|Hwfw:10|hflight path|h|r is unlocked and the quests above are in your log.",tip="There's no mage |cffe2c6ff|Hwfw:29|htrainer|h|r here. Every two levels, fly to Ironforge to train. It's a short flight.",talents={"Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster."},pins={{zone="Loch Modan",x=35,y=47,label="Thelsamar"}},quests={"Thelsamar","Stout to Kadrell","Mountaineer Kadrell","Rat Catching","Mountaineer Stormpike's Task","Thelsamar Blood Sausages","Ironband's Excavation"}},
  {kind="train",chapter=4,lv="12",lo=12,hi=12,place="Ironforge (fly)",title="Level 12: train",todo={"Fly to Ironforge, open the mage |cffe2c6ff|Hwfw:29|htrainer|h|r, and learn everything you can afford, including the new |cffe2c6ff|Hwfw:22|hrank|h|r of |cffffd200Conjure Food|r (Conjured Bread).","Spend your |cffe2c6ff|Hwfw:27|htalent|h|r point (|cff7fd4ffN|r): |cffffd200Improved Frostbolt|r."},done="you've learned the new ranks, your new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r, and you've spent your |cffe2c6ff|Hwfw:27|htalent|h|r point.",tip="From now on, train every even level and spend a |cffe2c6ff|Hwfw:27|htalent|h|r point every level. The Talents tab of this guide tells you which one.",bars={head="Action bar",rows={{id="slowfall",where="Right bar, button |cffffd2008|r |cff9a9a9acounting from the top|r"},{id="food2",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Muffin"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Food","Improved Frostbolt"}},
  {kind="quest",chapter=4,lv="12–14",lo=12,hi=14,place="Loch Modan",title="Troggs, rats and the mine",todo={"|cffffd200Rat Catching|r: kill the tunnel rat kobolds on the mountainside west of Thelsamar for |cffffd20012 Tunnel Rat Ears|r.","Finish |cffffd200The Trogg Threat|r and |cffffd200In Defense of the King's Lands|r in Stonesplinter Valley and hand them in at the southern tower. Take the next parts if they're offered.","|cffffd200Mountaineer Stormpike's Task|r: ride north to |cffffd200Mountaineer Stormpike|r at Algaz Station. He gives |cffffd200Filthy Paws|r: open the |cffffd200Miners' League Crates|r in the |cffffd200Silver Stream Mine|r for |cffffd2004 Miners' Gear|r. Then he gives |cffffd200Stormpike's Order|r, a letter for Stormwind (you go there at level 15).","Take any new quests you see. Loch Modan has 11 new ones in Forever."},done="you've handed in |cffffd200The Trogg Threat|r, |cffffd200In Defense of the King's Lands|r, |cffffd200Rat Catching|r and |cffffd200Filthy Paws|r, and you're level 14.",stuck="Fight the troggs in Stonesplinter Valley until you are.",talents={"Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster."},pins={{zone="Loch Modan",x=24.8,y=18.4,label="Mountaineer Stormpike (Algaz Station)"},{zone="Loch Modan",x=35,y=19,label="Silver Stream Mine"},{zone="Loch Modan",x=30,y=70,label="Stonesplinter Valley (troggs)"},{zone="Loch Modan",x=30,y=40,label="Tunnel rat kobolds (hills west of town)"}},quests={"Rat Catching","The Trogg Threat","In Defense of the King's Lands","Mountaineer Stormpike's Task","Mountaineer Stormpike","Filthy Paws","Miners' League Crates","Silver Stream Mine","Stormpike's Order"}},
  {kind="dungeon",chapter=4,lv="13–18",lo=13,hi=18,place="Under Ironforge",title="Your first dungeon: Hall of Thanes",todo={"A |cffe2c6ff|Hwfw:6|hdungeon|h|r is a private area for a group of 5 players. Hall of Thanes is new in Forever and sits under Ironforge.","Before going, have these quests: |cffffd200Important Heirlooms|r (Thom Filch) and |cffffd200Old Ironforge Incursion|r (from the quarry). Two more start inside.","Find a group: open the Looking For Group tool or ask in chat (\"LFG Hall of Thanes\").","Inside, stay behind the |cffe2c6ff|Hwfw:28|htank|h|r (the player the enemies attack), use Frostbolt, and don't attack before the tank does."},done="your group has beaten the last boss, or you've decided to skip it.",tip="The 5 quests here give about one whole level of |cffe2c6ff|Hwfw:31|hXP|h|r. Most |cffe2c6ff|Hwfw:6|hdungeon|h|r XP in Forever comes from quests, not kills.",talents={"Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster.","Level 15–17: |cffffd200Frostbite|r, 3 times. Your slowing spells can freeze enemies by themselves.","Level 18–19: |cffffd200Improved Frostbolt|r, 2 more times (5 of 5)."},quests={"Important Heirlooms","Old Ironforge Incursion"}},
  {kind="train",chapter=4,lv="14",lo=14,hi=14,place="Ironforge (fly)",title="Level 14: your first area spell",todo={"Learn |cffffd200Arcane Explosion|r. It hits every enemy around you, but costs a lot of mana.","You don't need it much while questing alone. It's for later, when you fight groups."},done="you've learned Arcane Explosion and it's on |cff7fd4ffShift|r + |cff7fd4ff1|r.",bars={head="Action bar",rows={{id="arcaneexplosion",where="|cff7fd4ffShift|r + |cff7fd4ff1|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 12–14: |cffffd200Improved Frostbolt|r, 3 times. Frostbolt casts faster."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Arcane Explosion"}},
  {kind="quest",chapter=4,lv="15",lo=15,hi=15,place="Stormwind",title="Mage quest: a free robe",todo={"Magis Sparkmantle in Kharanos gives |cffffd200Report to Jennea|r (optional). In Ironforge, go to Tinker Town and take the |cffffd200Deeprun Tram|r to Stormwind. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r, and hand |cffffd200Stormpike's Order|r to |cffffd200Furen Longbeard|r in the Dwarven District.","In the Mage Quarter, |cffffd200Jennea Cannon|r gives |cffffd200Investigate the Blue Recluse|r. Take the items from the table behind her, go to the |cffffd200Blue Recluse|r tavern, read the Cantation to make the creatures appear, beat them, and use a coffer on each while it's stunned. You need 3.","Next, |cffffd200Gathering Materials|r: |cffffd20010 Linen Cloth|r and |cffffd2006 Charged Rift Gems|r. The gems are in the Miners' League crates in the Silver Stream Mine in Loch Modan.","Give it all to |cffffd200Wynne Larson|r at Larson Clothiers in the Mage Quarter, then talk to her again for the |cffffd200Manaweave Robe|r."},done="you're wearing the |cffffd200Manaweave Robe|r, |cffffd200Stormpike's Order|r is handed in, and Stormwind's |cffe2c6ff|Hwfw:10|hflight path|h|r is unlocked.",talents={"Level 15–17: |cffffd200Frostbite|r, 3 times. Your slowing spells can freeze enemies by themselves."},pins={{zone="Ironforge",x=76.5,y=51,label="Deeprun Tram"},{zone="Stormwind",x=64,y=8,label="The tram arrives here"},{zone="Stormwind",x=49,y=86,label="Jennea Cannon (Mage Quarter)"},{zone="Stormwind",x=51.8,y=83.5,label="Wynne Larson (Larson Clothiers)"},{zone="Stormwind",x=66.3,y=62.1,label="Flight master"},{zone="Loch Modan",x=35,y=19,label="Silver Stream Mine (Charged Rift Gems)"}},quests={"Report to Jennea","Deeprun Tram","Stormpike's Order","Furen Longbeard","Jennea Cannon","Investigate the Blue Recluse","Blue Recluse","Gathering Materials","Wynne Larson","Manaweave Robe"}},
  {kind="quest",chapter=4,lv="15–18",lo=15,hi=18,place="Loch Modan",title="Finish Loch Modan",todo={"|cffffd200Thelsamar Blood Sausages|r: bear meat, boar intestines and spider ichor from the bears, boars and spiders around town. Hand it to Vidra.","|cffffd200Ironband's Excavation|r: ride to Prospector Ironband's dig site in the south-east and follow his quests.","Take the next parts of |cffffd200In Defense of the King's Lands|r from the dwarves at the southern tower and the dam if they're offered.","Your |cffe2c6ff|Hwfw:20|hquest log|h|r (|cff7fd4ffL|r) says how many of each thing you need. Skip |cffffd200WANTED: Chok'sul|r: it's an |cffe2c6ff|Hwfw:7|helite|h|r."},done="you're level 18 and the Thelsamar quests are handed in.",stuck="Fight the troggs and bears around Thelsamar until you are.",tip="Running out of quests? Westfall (south of Stormwind) and Redridge Mountains also fit this level.",talents={"Level 15–17: |cffffd200Frostbite|r, 3 times. Your slowing spells can freeze enemies by themselves.","Level 18–19: |cffffd200Improved Frostbolt|r, 2 more times (5 of 5)."},pins={{zone="Loch Modan",x=35,y=47,label="Thelsamar"},{zone="Loch Modan",x=65,y=65,label="Ironband's Excavation"}},quests={"Thelsamar Blood Sausages","Ironband's Excavation","In Defense of the King's Lands","WANTED: Chok'sul"}},
  {kind="train",chapter=4,lv="16",lo=16,hi=16,place="Ironforge (fly)",title="Level 16: Flamestrike",todo={"Fly to Ironforge and learn |cffffd200Flamestrike|r plus any new ranks.","Flamestrike burns an area on the ground. Cast it right after Frost Nova when several enemies are |cffe2c6ff|Hwfw:11|hfrozen|h|r together."},done="Flamestrike is on |cff7fd4ffShift|r + |cff7fd4ff3|r.",bars={head="Action bar",rows={{id="flamestrike",where="|cff7fd4ffShift|r + |cff7fd4ff3|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 15–17: |cffffd200Frostbite|r, 3 times. Your slowing spells can freeze enemies by themselves."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Flamestrike"}},
  {kind="train",chapter=4,lv="18",lo=18,hi=18,place="Ironforge (fly)",title="Level 18: Remove Lesser Curse",todo={"Learn |cffffd200Remove Lesser Curse|r and new ranks.","In dungeons, when a party member has a curse on them, click them and cast it. Groups love mages who do this."},done="Remove Lesser Curse is on |cff7fd4ffShift|r + |cff7fd4ff9|r.",bars={head="Action bar",rows={{id="removecurse",where="|cff7fd4ffShift|r + |cff7fd4ff9|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 18–19: |cffffd200Improved Frostbolt|r, 2 more times (5 of 5)."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Remove Lesser Curse"}},
  {kind="train",chapter=5,lv="20",lo=20,hi=20,place="Ironforge",title="Level 20: the big one",todo={"Learn everything: |cffffd200Blink|r, |cffffd200Blizzard|r, |cffffd200Evocation|r, |cffffd200Mana Shield|r, |cffffd200Teleport: Ironforge|r, |cffffd200Teleport: Stormwind|r and new ranks, including a new |cffffd200Conjure Water|r.","Buy a few |cffffd200Runes of Teleportation|r from the |cffe2c6ff|Hwfw:23|hreagent vendor|h|r. Teleports use them up.","Put Blink on key |cff7fd4ff7|r. It jumps you forward a short distance. Use it to get away."},done="Blink is on |cff7fd4ff7|r, you know both teleports, you have Runes of Teleportation, and your new water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r.",tip="Teleports mean you can leave your |cffe2c6ff|Hwfw:13|hHearthstone|h|r set to wherever you're questing and still reach the city whenever you like.",bars={head="Action bar",rows={{id="blink",where="Key |cff7fd4ff7|r |cff9a9a9amain bar|r"},{id="blizzard",where="|cff7fd4ffShift|r + |cff7fd4ff2|r |cff9a9a9abottom left bar|r"},{id="evocation",where="|cff7fd4ffShift|r + |cff7fd4ff6|r |cff9a9a9abottom left bar|r"},{id="manashield",where="|cff7fd4ffShift|r + |cff7fd4ff=|r |cff9a9a9abottom left bar|r"},{id="tp_if",where="Right bar, button |cffffd20010|r |cff9a9a9acounting from the top|r"},{id="tp_sw",where="Right bar, button |cffffd20011|r |cff9a9a9acounting from the top|r"},{id="water3",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Fresh Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 20: |cffffd200Ice Lance|r, once. Triple damage to frozen enemies. Your best new trick."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Blink","Blizzard","Evocation","Mana Shield","Teleport: Ironforge","Teleport: Stormwind","Conjure Water","Runes of Teleportation"}},
  {kind="talent",chapter=5,lv="20",lo=20,hi=20,place="Talents (N)",title="Level 20: Ice Lance",todo={"Put this level's |cffe2c6ff|Hwfw:27|htalent|h|r point into |cffffd200Ice Lance|r.","Open your |cffe2c6ff|Hwfw:26|hspellbook|h|r (|cff7fd4ffP|r) and put Ice Lance on key |cff7fd4ff4|r."},done="Ice Lance is on |cff7fd4ff4|r.",tip="Ice Lance does triple damage to a |cffe2c6ff|Hwfw:11|hfrozen|h|r enemy. New combo: Frostbolt > enemy reaches you > Frost Nova > step back > Ice Lance > Frostbolt.",bars={head="Action bar",rows={{id="icelance",where="Key |cff7fd4ff4|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 20: |cffffd200Ice Lance|r, once. Triple damage to frozen enemies. Your best new trick."},quests={"Ice Lance"}},
  {kind="travel",chapter=5,lv="20",lo=20,hi=20,place="Loch Modan > Wetlands",title="Travel to the Wetlands",todo={"From Loch Modan, take the road north through the pass (Dun Algaz) into the |cffffd200Wetlands|r.","Stay on the road. Some enemies along it are stronger than you.","At the crossroads, |cffffd200Einar Stonegrip|r gives |cffffd200Daily Delivery|r: a bundle of skins for the tanner in Menethil.","Follow the road west to |cffffd200Menethil Harbor|r on the coast."},done="you've reached Menethil Harbor with |cffffd200Daily Delivery|r in your |cffe2c6ff|Hwfw:20|hquest log|h|r.",talents={"Level 20: |cffffd200Ice Lance|r, once. Triple damage to frozen enemies. Your best new trick."},pins={{zone="Loch Modan",x=24.8,y=18.4,label="Algaz Station: road north"},{zone="Wetlands",x=53,y=72,label="Dun Algaz: you come in here"},{zone="Wetlands",x=49.8,y=39.4,label="Einar Stonegrip (crossroads)"},{zone="Wetlands",x=10.5,y=60,label="Menethil Harbor"}},quests={"Wetlands","Einar Stonegrip","Daily Delivery","Menethil Harbor"}},
  {kind="home",chapter=6,lv="20–22",lo=20,hi=22,place="Menethil Harbor",title="Settle in Menethil",todo={"Make the |cffe2c6ff|Hwfw:15|hinn|h|r your home. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","Hand |cffffd200Daily Delivery|r to |cffffd200James Halloran|r, the tanner, and take |cffffd200Young Crocolisk Skins|r from him.","Take every quest in town: |cffffd200Claws from the Deep|r (Karl Boran), |cffffd200The Greenwarden|r (First Mate Fitzsimmons), |cffffd200Digging Through the Ooze|r (Sida), |cffffd200In Search of The Excavation Team|r (Tarrel Rockweaver) and more."},done="Menethil Harbor is your home, the |cffe2c6ff|Hwfw:10|hflight path|h|r is unlocked and the town's quests are in your log.",talents={"Level 20: |cffffd200Ice Lance|r, once. Triple damage to frozen enemies. Your best new trick.","Level 21–24: |cffffd200Ice Shards|r, 4 times. Your Frost critical hits do more damage."},pins={{zone="Wetlands",x=10.5,y=60,label="Menethil Harbor"}},quests={"Daily Delivery","James Halloran","Young Crocolisk Skins","Claws from the Deep","The Greenwarden","Digging Through the Ooze","In Search of The Excavation Team"}},
  {kind="train",chapter=6,lv="22",lo=22,hi=22,place="Ironforge (teleport)",title="Level 22: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r, including a new |cffffd200Conjure Food|r (Conjured Rye). Put it on |cff7fd4ffAlt|r + |cff7fd4ff2|r.","Hearth back to Menethil Harbor."},done="you've learned the new ranks and your new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r.",bars={head="Action bar",rows={{id="food3",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Bread"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 21–24: |cffffd200Ice Shards|r, 4 times. Your Frost critical hits do more damage."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}},quests={"Conjure Food"}},
  {kind="quest",chapter=6,lv="21–24",lo=21,hi=24,place="Wetlands",title="Quest the Wetlands",todo={"Coast first: |cffffd200Claws from the Deep|r: kill |cffffd20012 Bluegill murlocs|r and |cffffd200Gobbler|r, north of Menethil, for his head. Kill young crocolisks in the marsh for |cffffd200Young Crocolisk Skins|r.","Then inland: give |cffffd200The Greenwarden|r to |cffffd200Rethiel the Greenwarden|r. He gives |cffffd200Tramping Paws|r (gnolls to the south-east), then |cffffd200Fire Taboo|r and |cffffd200Blisters on The Land|r.","|cffffd200In Search of The Excavation Team|r: talk to Merrin Rockweaver at Whelgar's Excavation Site and follow his quests.","|cffffd200Digging Through the Ooze|r: kill the black oozes at |cffffd200Ironbeard's Tomb|r (north, past Dun Modr) until one drops |cffffd200Sida's Bag|r. The Wetlands got 20+ new quests in Forever: take everything you find."},done="you're level 24 and have handed in |cffffd200Claws from the Deep|r, |cffffd200Young Crocolisk Skins|r and |cffffd200Tramping Paws|r.",stuck="Fight the murlocs along the coast until you are.",talents={"Level 21–24: |cffffd200Ice Shards|r, 4 times. Your Frost critical hits do more damage."},pins={{zone="Wetlands",x=17,y=39,label="Gobbler and the murloc coast"},{zone="Wetlands",x=56.4,y=40.4,label="Rethiel the Greenwarden"},{zone="Wetlands",x=44,y=24,label="Ironbeard's Tomb (oozes)"},{zone="Wetlands",x=34,y=42,label="Whelgar's Excavation Site"}},quests={"Claws from the Deep","Gobbler","Young Crocolisk Skins","The Greenwarden","Rethiel the Greenwarden","Tramping Paws","Fire Taboo","Blisters on The Land","In Search of The Excavation Team","Digging Through the Ooze","Ironbeard's Tomb","Sida's Bag"}},
  {kind="train",chapter=6,lv="24",lo=24,hi=24,place="Ironforge (teleport)",title="Level 24: Counterspell",todo={"Learn |cffffd200Counterspell|r and new ranks. When an enemy is casting a spell (you'll see a cast bar under its name), press Counterspell to stop it."},done="Counterspell is on |cff7fd4ff-|r.",bars={head="Action bar",rows={{id="counterspell",where="Key |cff7fd4ff-|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 21–24: |cffffd200Ice Shards|r, 4 times. Your Frost critical hits do more damage."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Counterspell"}},
  {kind="talent",chapter=6,lv="25",lo=25,hi=25,place="Talents (N)",title="Level 25: Shatter and Legacy",todo={"|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Shatter|r. Your spells crit much more often on |cffe2c6ff|Hwfw:11|hfrozen|h|r enemies, so Frost Nova + Ice Lance hits even harder.","Around now you get your first |cffffd200|cffe2c6ff|Hwfw:16|hLegacy|h|r|r point. Press |cff7fd4ffY|r and put it in |cffffd200Thrill of Adventure|r: every kill gives back some health and mana."},done="your |cffe2c6ff|Hwfw:27|htalent|h|r point is in Shatter and your |cffe2c6ff|Hwfw:16|hLegacy|h|r point is spent.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 25–27: |cffffd200Shatter|r, 3 times. Many more critical hits on frozen enemies."},quests={"Shatter","Legacy","Thrill of Adventure"}},
  {kind="dungeon",chapter=6,lv="24–29",lo=24,hi=29,place="Wetlands",title="Dungeon: Excavation Site (optional)",todo={"Another new |cffe2c6ff|Hwfw:6|hdungeon|h|r, in the Wetlands. Best at levels 26–29.","Collect its quests first: |cffffd200Caitlin Grassman|r in Menethil and |cffffd200Dorin Songblade|r in Lakeshire (Redridge). Others come from the Wetlands quest chains.","Find a group the same way as Hall of Thanes."},done="your group has beaten the last boss, or you've decided to skip it.",talents={"Level 21–24: |cffffd200Ice Shards|r, 4 times. Your Frost critical hits do more damage.","Level 25–27: |cffffd200Shatter|r, 3 times. Many more critical hits on frozen enemies.","Level 28: |cffffd200Ice Shards|r, once more (5 of 5).","Level 29: |cffffd200Ice Block|r, once. Your \"don't die\" button."},pins={{zone="Wetlands",x=10.5,y=60,label="Caitlin Grassman (Menethil)"},{zone="Wetlands",x=34,y=42,label="Whelgar's Excavation Site"},{zone="Redridge Mountains",x=26,y=46,label="Dorin Songblade (Lakeshire)"}},quests={"Caitlin Grassman","Dorin Songblade"}},
  {kind="train",chapter=6,lv="26",lo=26,hi=26,place="Stormwind (teleport)",title="Level 26: Cone of Cold and another mage quest",todo={"Learn |cffffd200Cone of Cold|r and put it on key |cff7fd4ff8|r. It hits and slows everything in front of you.","Mage quest: |cffffd200Jennea Cannon|r sends you to |cffffd200High Sorcerer Andromath|r at the top of the Wizard's Sanctum. |cffffd200Ur's Treatise on Shadow Magic|r: climb the |cffffd200Tower of Ilgalar|r in eastern Redridge and take the book. You don't have to fight the |cffe2c6ff|Hwfw:7|helite|h|r at the top. Polymorph the gnolls, kill their dogs first and Counterspell the dogs' Mana Burn.","|cffffd200Pristine Spider Silk|r: 8 silk from the spiders in and just east of Raven Hill Cemetery, Duskwood. Flying to Sentinel Hill in Westfall and walking east is quickest.","Give the silk to |cffffd200Wynne Larson|r and talk to her again to pick the |cffffd200Astral Knot Robe|r or |cffffd200Astral Knot Blouse|r."},done="Cone of Cold is on |cff7fd4ff8|r and you're wearing the |cffffd200Astral Knot Robe|r or |cffffd200Blouse|r.",tip="The tower is dangerous alone at this level. If you die inside, you can come back to life anywhere in the tower: next to the book, then grab it and leave.",bars={head="Action bar",rows={{id="coneofcold",where="Key |cff7fd4ff8|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 25–27: |cffffd200Shatter|r, 3 times. Many more critical hits on frozen enemies."},pins={{zone="Stormwind",x=49,y=86,label="Jennea Cannon and Andromath (Mage Quarter)"},{zone="Stormwind",x=51.8,y=83.5,label="Wynne Larson"},{zone="Redridge Mountains",x=79,y=49,label="Tower of Ilgalar (the book)"},{zone="Duskwood",x=20,y=45,label="Raven Hill Cemetery (spiders)"}},quests={"Cone of Cold","Jennea Cannon","High Sorcerer Andromath","Ur's Treatise on Shadow Magic","Tower of Ilgalar","Pristine Spider Silk","Wynne Larson","Astral Knot Robe","Astral Knot Blouse"}},
  {kind="quest",chapter=6,lv="27–28",lo=27,hi=28,place="Wetlands",title="Finish the Wetlands",todo={"Finish your Wetlands quests: the Greenwarden chain, the excavation team and Sida's bag.","At level 25 Harlo Barnaby in Menethil gives |cffffd200Fall of Dun Modr|r: find |cffffd200Longbraid the Grim|r near the ruins of Dun Modr in the north. His next quest is for a group.","If the north part feels too hard, go to |cffffd200Redridge Mountains|r or |cffffd200Duskwood|r (both near Stormwind) for a few levels."},done="you're level 28 and your Wetlands quests are handed in.",stuck="Fight the crocolisks or gnolls in the Wetlands until you are.",talents={"Level 25–27: |cffffd200Shatter|r, 3 times. Many more critical hits on frozen enemies.","Level 28: |cffffd200Ice Shards|r, once more (5 of 5)."},pins={{zone="Wetlands",x=10.5,y=60,label="Menethil Harbor"},{zone="Wetlands",x=48,y=15,label="Dun Modr"}},quests={"Fall of Dun Modr","Longbraid the Grim","Redridge Mountains","Duskwood"}},
  {kind="train",chapter=6,lv="28",lo=28,hi=28,place="Ironforge (teleport)",title="Level 28: mana gems",todo={"Learn new ranks, including |cffffd200Conjure Mana Agate|r.","Cast it and put the |cffffd200Mana Agate|r on |cff7fd4ffShift|r + |cff7fd4ff5|r. In a hard fight, press it for instant mana. Conjure a new one after each use."},done="your Mana Agate is on |cff7fd4ffShift|r + |cff7fd4ff5|r.",bars={head="Action bar",rows={{id="conjuregem",where="Right bar, button |cffffd2006|r |cff9a9a9acounting from the top|r"},{id="managem",where="|cff7fd4ffShift|r + |cff7fd4ff5|r |cff9a9a9abottom left bar|r"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 28: |cffffd200Ice Shards|r, once more (5 of 5)."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}},quests={"Conjure Mana Agate","Mana Agate"}},
  {kind="talent",chapter=6,lv="29",lo=29,hi=29,place="Talents (N)",title="Level 29: Ice Block",todo={"|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Ice Block|r. Put it on key |cff7fd4ff9|r.","When you're about to die, press it: you're |cffe2c6ff|Hwfw:11|hfrozen|h|r in a block of ice and nothing can hurt you for 10 seconds. Press it again to come out early."},done="Ice Block is on key |cff7fd4ff9|r.",bars={head="Action bar",rows={{id="iceblock",where="Key |cff7fd4ff9|r |cff9a9a9amain bar|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 29: |cffffd200Ice Block|r, once. Your \"don't die\" button."},quests={"Ice Block"}},
  {kind="quest",chapter=7,lv="28–30",lo=28,hi=30,place="Darkshire, Duskwood",title="Duskwood",todo={"Go to Stormwind (from Menethil Harbor: fly to Ironforge and take the Deeprun Tram), then follow the road south-east through Elwynn Forest into |cffffd200Duskwood|r, a dark forest. The town is |cffffd200Darkshire|r, on the east side. Make the |cffe2c6ff|Hwfw:15|hinn|h|r your home and unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","Take every quest in Darkshire. Start with |cffffd200Worgen in the Woods|r from Calor (wolf-men in Brightwood Grove, north-west of town) and |cffffd200The Night Watch|r from Commander Althea Ebonlock (skeletons in Raven Hill Cemetery, far west).","Many Duskwood quests lead into one story about |cffffd200Morbent Fel|r, a necromancer at the Tranquil Gardens Cemetery. Keep following it: it's one of the best stories in the game.","Skip quests marked |cffffd200|cffe2c6ff|Hwfw:7|hElite|h|r|r, like |cffffd200Mor'Ladim|r, unless you have a group. Move on at level 30."},done="you're level 30 and have handed in |cffffd200Worgen in the Woods|r and |cffffd200The Night Watch|r.",stuck="Fight the worgen in Brightwood Grove until you are.",tip="Worgen walk in pairs. They're humanoids, so Polymorph works on them: turn one into a sheep, kill the other, then fight the sheep.",talents={"Level 28: |cffffd200Ice Shards|r, once more (5 of 5).","Level 29: |cffffd200Ice Block|r, once. Your \"don't die\" button.","Level 30–31: |cffffd200Fingers of Frost|r, 2 times. Sometimes your next spell treats the enemy as frozen: cast Ice Lance."},pins={{zone="Duskwood",x=73.5,y=46,label="Darkshire"},{zone="Duskwood",x=64,y=36,label="Brightwood Grove (worgen)"},{zone="Duskwood",x=20,y=45,label="Raven Hill Cemetery (skeletons)"},{zone="Duskwood",x=80,y=70,label="Tranquil Gardens Cemetery"}},quests={"Duskwood","Darkshire","Worgen in the Woods","The Night Watch","Morbent Fel","Elite","Mor'Ladim"}},
  {kind="train",chapter=7,lv="30",lo=30,hi=30,place="Ironforge (teleport)",title="Level 30: Ice Armor and the wand quest",todo={"Learn |cffffd200Ice Armor|r (it replaces Frost Armor and is stronger), |cffffd200Teleport: Darnassus|r and new ranks, including a new |cffffd200Conjure Water|r.","|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Fingers of Frost|r. Sometimes your next spell treats the enemy as |cffe2c6ff|Hwfw:11|hfrozen|h|r: when that happens, cast Ice Lance for triple damage.","Take |cffffd200Journey to the Marsh|r from the mage |cffe2c6ff|Hwfw:29|htrainer|h|r. This starts the quest for the |cffffd200Icefury Wand|r (see the later step)."},done="Ice Armor is on, your new water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r, your |cffe2c6ff|Hwfw:27|htalent|h|r point is in Fingers of Frost, and |cffffd200Journey to the Marsh|r is in your log.",bars={head="Action bar",rows={{id="icearmor",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Frost Armor"},{id="water4",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Purified Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 30–31: |cffffd200Fingers of Frost|r, 2 times. Sometimes your next spell treats the enemy as frozen: cast Ice Lance."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Ice Armor","Teleport: Darnassus","Conjure Water","Fingers of Frost","Journey to the Marsh","Icefury Wand"}},
  {kind="quest",chapter=7,lv="30–32",lo=30,hi=32,place="Arathi Highlands",title="Arathi Highlands",todo={"Fly to |cffffd200Menethil Harbor|r and ride north over the big bridge (Thandol Span) into |cffffd200Arathi Highlands|r, a wide open grassland.","In the middle is |cffffd200Refuge Pointe|r, the Alliance camp. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r and make it your home.","Take every quest. Captain Nials's |cffffd200Northfold Manor|r sends you to the Syndicate in the north-west. Sentinel Glynda Nal'Shea sends you after the Witherbark trolls in the south-east.","Wand quest (|cffffd200Items of Power|r): kill Witherbark trolls at Witherbark Village for |cffffd20010 Witherbark Totem Sticks|r. At the |cffffd200Circle of Outer Binding|r in the middle of the |cffe2c6ff|Hwfw:32|hzone|h|r, stand on the stone in the centre and use the sticks. After about 10 seconds lightning strikes: loot the |cffffd200Bolt Charged Bramble|r from the stone. Three elementals guard the circle: |cffe2c6ff|Hwfw:18|hpull|h|r them one at a time.","Stay out of |cffffd200Stromgarde Keep|r (west) unless you're in a group: it's full of |cffe2c6ff|Hwfw:7|helite|h|r enemies. |cffffd200Hammerfall|r (east) is a Horde town. Move on at level 32."},done="you're level 32 and have handed in |cffffd200Northfold Manor|r.",stuck="Fight the Syndicate around Northfold Manor until you are.",tip="The Syndicate are humanoids: when two come at you, Polymorph the second one.",talents={"Level 30–31: |cffffd200Fingers of Frost|r, 2 times. Sometimes your next spell treats the enemy as frozen: cast Ice Lance.","Level 32: |cffffd200Cold Snap|r, once. Resets your Frost cooldowns, so you can Ice Block or Frost Nova again."},pins={{zone="Arathi Highlands",x=44,y=89,label="Thandol Span (from the Wetlands)"},{zone="Arathi Highlands",x=45.8,y=47.6,label="Refuge Pointe"},{zone="Arathi Highlands",x=32,y=28,label="Northfold Manor (Syndicate)"},{zone="Arathi Highlands",x=66,y=68,label="Witherbark Village (trolls)"},{zone="Arathi Highlands",x=52,y=50,label="Circle of Outer Binding (wand quest)"},{zone="Arathi Highlands",x=25,y=30,label="Stromgarde Keep (elites)"},{zone="Arathi Highlands",x=73,y=33,label="Hammerfall (Horde town)"}},quests={"Menethil Harbor","Arathi Highlands","Refuge Pointe","Northfold Manor","Items of Power","Circle of Outer Binding","Bolt Charged Bramble","Stromgarde Keep","Hammerfall"}},
  {kind="train",chapter=7,lv="32",lo=32,hi=32,place="Ironforge (teleport)",title="Level 32: Cold Snap",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r, including a new |cffffd200Conjure Food|r (Conjured Pumpernickel).","|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Cold Snap|r. Put it on |cff7fd4ffShift|r + |cff7fd4ff8|r. It resets your Frost cooldowns, so you get a second Ice Block or Frost Nova.","Hearth back to Refuge Pointe and carry on."},done="Cold Snap is on |cff7fd4ffShift|r + |cff7fd4ff8|r and your new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r.",bars={head="Action bar",rows={{id="coldsnap",where="|cff7fd4ffShift|r + |cff7fd4ff8|r |cff9a9a9abottom left bar|r"},{id="food4",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Rye"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 32: |cffffd200Cold Snap|r, once. Resets your Frost cooldowns, so you can Ice Block or Frost Nova again."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}},quests={"Conjure Food","Cold Snap"}},
  {kind="quest",chapter=7,lv="32",lo=32,hi=32,place="Southshore, Hillsbrad",title="Southshore",todo={"From Refuge Pointe, ride west through the gate in the huge wall (Thoradin's Wall) into Hillsbrad Foothills. Follow the road south to |cffffd200Southshore|r. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","Take the town's quests. |cffffd200Down the Coast|r from Lieutenant Farren Orinelle (murlocs on the beach) and |cffffd200Syndicate Assassins|r from Marshal Redpath (in the Alterac Mountains, north) are quick |cffe2c6ff|Hwfw:31|hXP|h|r.","Talk to |cffffd200Emissary Jacques|r to start the new |cffffd200City of Dalaran|r |cffe2c6ff|Hwfw:6|hdungeon|h|r (levels 28–35). Optional.","Southshore also has a boat to Auberdine. Move on at about level 33."},done="you're level 33 and have handed in |cffffd200Down the Coast|r and |cffffd200Syndicate Assassins|r.",stuck="Fight the murlocs on the beach south of Southshore until you are.",tip="From here on, on |cffe2c6ff|Hwfw:19|hPvP|h|r servers, Horde players can attack you. Frost Nova and Blink are your escape.",talents={"Level 32: |cffffd200Cold Snap|r, once. Resets your Frost cooldowns, so you can Ice Block or Frost Nova again."},pins={{zone="Arathi Highlands",x=20,y=30,label="Gate in Thoradin's Wall (west)"},{zone="Hillsbrad Foothills",x=50,y=55,label="Southshore"},{zone="Hillsbrad Foothills",x=40,y=74,label="Murloc beach"}},quests={"Southshore","Down the Coast","Syndicate Assassins","Emissary Jacques","City of Dalaran"}},
  {kind="quest",chapter=8,lv="33–35",lo=33,hi=35,place="Stranglethorn Vale (north)",title="Stranglethorn: Rebel Camp and the hunters",todo={"Fly to |cffffd200Darkshire|r and follow the road south out of Duskwood into |cffffd200Stranglethorn Vale|r, a big jungle. Right at the |cffe2c6ff|Hwfw:32|hzone|h|r edge, turn west to the |cffffd200Rebel Camp|r.","Lieutenant Doren's quests at the Rebel Camp send you against the Kurzen soldiers at their compound, east of the camp.","Just south is |cffffd200Nesingwary's Expedition|r, a hunting camp. Take |cffffd200Tiger Mastery|r, |cffffd200Panther Mastery|r and |cffffd200Raptor Mastery|r: each sends you to hunt one kind of animal, and later parts send you after bigger ones.","Pages of |cffffd200The Green Hills of Stranglethorn|r drop from almost everything here. Keep them: when you have a full chapter, hand it to Barnil Stonepot at Nesingwary's camp for |cffe2c6ff|Hwfw:31|hXP|h|r."},done="you're level 35 and have handed in the first parts of |cffffd200Tiger Mastery|r, |cffffd200Panther Mastery|r and |cffffd200Raptor Mastery|r.",stuck="Fight the tigers and panthers around Nesingwary's camp until you are.",tip="Grom'gol, on the west coast, is a Horde camp. Stay away from it.",talents={"Level 33–35: |cffffd200Improved Cone of Cold|r, 3 times. Cone of Cold hits harder."},pins={{zone="Stranglethorn Vale",x=38,y=3.5,label="Rebel Camp"},{zone="Stranglethorn Vale",x=35.6,y=10.6,label="Nesingwary's Expedition"},{zone="Stranglethorn Vale",x=44,y=10,label="Kurzen's Compound"},{zone="Stranglethorn Vale",x=32,y=28,label="Grom'gol (Horde camp)"}},quests={"Darkshire","Stranglethorn Vale","Rebel Camp","Nesingwary's Expedition","Tiger Mastery","Panther Mastery","Raptor Mastery","The Green Hills of Stranglethorn"}},
  {kind="quest",chapter=8,lv="33–35",lo=33,hi=35,place="Several places",title="Finish the wand quest",todo={"Take |cffffd200Journey to the Marsh|r to |cffffd200Tabetha|r, whose hut is in the middle of Dustwallow Marsh (fly to Theramore, follow the road south and cut east into the marsh: the east side has stronger enemies). She gives |cffffd200Hidden Secrets|r and |cffffd200Items of Power|r.","|cffffd200Hidden Secrets|r: talk to |cffffd200Magus Tirth|r at the Mirage Raceway in Thousand Needles. |cffffd200Get the Scoop|r: cross the racetrack to the tower, type |cff7fd4ff/target \"Plucky\" Johnson|r to target the little grey chicken, type |cff7fd4ff/beckon|r, then talk to him and go back to Tirth.","|cffffd200Rituals of Power|r (from Tirth): the book is in the |cffffd200Scarlet Monastery Library|r (a |cffe2c6ff|Hwfw:6|hdungeon|h|r, so you need a group). At the start of the long hall before Arcanist Doan, it sticks out of a bookshelf on your left.","|cffffd200Items of Power|r: a |cffffd200Jade|r (|cffe2c6ff|Hwfw:2|hauction house|h|r) and the |cffffd200Bolt Charged Bramble|r from Arathi (see the Arathi step). Hand everything to Tabetha, take |cffffd200Mage's Wand|r, wait for her ritual, and pick the |cffffd200Icefury Wand|r."},done="the |cffffd200Icefury Wand|r is equipped, or you've decided to skip it.",tip="This quest sends you around the world. It's optional. If it feels like too much, skip it.",talents={"Level 33–35: |cffffd200Improved Cone of Cold|r, 3 times. Cone of Cold hits harder."},pins={{zone="Dustwallow Marsh",x=46,y=57,label="Tabetha's hut"},{zone="Thousand Needles",x=78.3,y=75.7,label="Magus Tirth (Mirage Raceway)"},{zone="Tirisfal Glades",x=83,y=33,label="Scarlet Monastery"}},quests={"Journey to the Marsh","Tabetha","Hidden Secrets","Items of Power","Magus Tirth","Get the Scoop","Rituals of Power","Scarlet Monastery Library","Jade","Bolt Charged Bramble","Mage's Wand","Icefury Wand"}},
  {kind="train",chapter=8,lv="34",lo=34,hi=34,place="Ironforge (teleport)",title="Level 34: Mage Armor",todo={"Learn |cffffd200Mage Armor|r and new ranks at the |cffe2c6ff|Hwfw:29|htrainer|h|r. Keep Ice Armor on while questing; swap to Mage Armor for long |cffe2c6ff|Hwfw:6|hdungeon|h|r fights.","Optional, from level 35: the |cffe2c6ff|Hwfw:29|htrainer|h|r offers |cffffd200Return to the Marsh|r, a hard chain from Tabetha (an |cffe2c6ff|Hwfw:7|helite|h|r demon and an Uldaman boss) that ends with the |cffffd200Celestial Orb|r. Do it with friends or later."},done="Mage Armor is on your right bar.",bars={head="Action bar",rows={{id="magearmor",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r"}},notes={"New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 33–35: |cffffd200Improved Cone of Cold|r, 3 times. Cone of Cold hits harder."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}},quests={"Mage Armor","Return to the Marsh","Celestial Orb"}},
  {kind="quest",chapter=8,lv="35–37",lo=35,hi=37,place="Booty Bay, Stranglethorn",title="Stranglethorn: Booty Bay",todo={"Follow the main road all the way south to |cffffd200Booty Bay|r, a goblin port built into a cliff. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r and make the |cffe2c6ff|Hwfw:15|hinn|h|r your home.","Booty Bay is neutral: Horde players use it too, and the goblin guards attack anyone who starts a fight in town.","Take |cffffd200Singing Blue Shards|r from Crank Fizzlebub (crystal-backed basilisks in the middle of the |cffe2c6ff|Hwfw:32|hzone|h|r) and the pirate quests that start with |cffffd200The Bloodsail Buccaneers|r from First Mate Crazz.","Keep doing the Nesingwary hunting quests as new parts open. Move on at level 37."},done="you're level 37 and have handed in |cffffd200Singing Blue Shards|r.",stuck="Fight the pirates or raptors along the coast near Booty Bay until you are.",tip="Booty Bay has a boat to Ratchet in Kalimdor. That helps with the wand quest in Dustwallow Marsh.",talents={"Level 33–35: |cffffd200Improved Cone of Cold|r, 3 times. Cone of Cold hits harder.","Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana."},pins={{zone="Stranglethorn Vale",x=27,y=77,label="Booty Bay"},{zone="Stranglethorn Vale",x=38,y=3.5,label="Rebel Camp"},{zone="Stranglethorn Vale",x=35.6,y=10.6,label="Nesingwary's Expedition"}},quests={"Booty Bay","Singing Blue Shards","The Bloodsail Buccaneers"}},
  {kind="dungeon",chapter=8,lv="35–40",lo=35,hi=40,place="Tirisfal Glades",title="Dungeon: Scarlet Monastery (optional)",todo={"Four short |cffe2c6ff|Hwfw:6|hdungeon|h|r wings, run by crazed crusaders: |cffffd200|cffe2c6ff|Hwfw:12|hGraveyard|h|r|r (around level 30), |cffffd200Library|r (around 33), |cffffd200Armory|r (around 36) and |cffffd200Cathedral|r (around 38).","It's deep in Horde land, so don't walk there. Find a group with the Looking For Group tool and let the group summon you at the meeting stone outside.","Collect the Alliance quests first: |cffffd200Mythology of the Titans|r (Librarian Mae Paledust, Hall of Explorers in Ironforge) and |cffffd200In the Name of the Light|r (Raleigh the Devout, Southshore |cffe2c6ff|Hwfw:15|hinn|h|r).","Wand quest: the |cffffd200Rituals of Power|r book is on a side table in the Library.","Skip it if you'd rather keep questing."},done="your group has finished the wings you wanted, or you've decided to skip it.",tip="Save Blizzard and Arcane Explosion until the |cffe2c6ff|Hwfw:28|htank|h|r has every enemy's attention, or they all run at you.",talents={"Level 33–35: |cffffd200Improved Cone of Cold|r, 3 times. Cone of Cold hits harder.","Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana.","Level 39: |cffffd200Improved Blizzard|r, once. Blizzard slows the enemies in it.","Level 40: |cffffd200Ice Barrier|r, once. A damage-absorbing shield. Use it before every fight."},pins={{zone="Tirisfal Glades",x=83,y=33,label="Scarlet Monastery"}},quests={"Graveyard","Library","Armory","Cathedral","Mythology of the Titans","In the Name of the Light","Rituals of Power"}},
  {kind="train",chapter=8,lv="36",lo=36,hi=36,place="Ironforge (teleport)",title="Level 36: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r. New ranks replace the old ones on your bars by themselves.","Hearth back to Booty Bay."},done="you've learned every new |cffe2c6ff|Hwfw:22|hrank|h|r your |cffe2c6ff|Hwfw:29|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}}},
  {kind="travel",chapter=9,lv="37",lo=37,hi=37,place="Redridge > Riverglades",title="Travel to the Riverglades",todo={"Fly to |cffffd200Lakeshire|r in Redridge Mountains. No |cffe2c6ff|Hwfw:10|hflight path|h|r there yet? Fly to Darkshire and ride north-east into Redridge.","From Lakeshire, follow the road north toward the Burning Steppes. Near the edge of the map, a signpost at a crossroads points to the Riverglades: take the right-hand path into the hills.","Follow that road south to |cffffd200Farholde Keep|r, the Alliance town in the Riverglades (a new |cffe2c6ff|Hwfw:32|hzone|h|r in WoW Forever).","Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r (Gretchen Mayberry) and make the |cffe2c6ff|Hwfw:15|hinn|h|r your home. From now on you can fly straight between Farholde Keep and Lakeshire."},done="Farholde Keep is your home (hover over your |cffe2c6ff|Hwfw:13|hHearthstone|h|r to check) and you've unlocked its |cffe2c6ff|Hwfw:10|hflight path|h|r.",talents={"Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana."},pins={{zone="Redridge Mountains",x=30.6,y=59.4,label="Lakeshire flight path"}},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Lakeshire","Farholde Keep"}},
  {kind="quest",chapter=9,lv="37–40",lo=37,hi=40,place="Farholde Keep, Riverglades",title="Riverglades: around Farholde Keep",todo={"Take every quest in Farholde Keep. Many come from |cffffd200Demar Brant|r, the knight in charge, and the people around him. There are over 70 Alliance quests in this |cffe2c6ff|Hwfw:32|hzone|h|r.","Riverglades quests come in waves: when you finish a batch, new ones usually appear back in Farholde Keep. Check the town after every few turn-ins.","Start with the farms and lookouts close to the keep. The enemies get tougher the further north you go.","The Horde quests here too (their town is Rog'mar). On |cffe2c6ff|Hwfw:19|hPvP|h|r servers, keep your escape buttons ready. Move on at level 40."},done="you're level 40.",stuck="Fight the enemies near your current quests in the south of the |cffe2c6ff|Hwfw:32|hzone|h|r until you are.",tip="There's no Riverglades map on this site yet. Use your in-game map (|cff7fd4ffM|r): Farholde Keep is in the south of the |cffe2c6ff|Hwfw:32|hzone|h|r.",talents={"Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana.","Level 39: |cffffd200Improved Blizzard|r, once. Blizzard slows the enemies in it.","Level 40: |cffffd200Ice Barrier|r, once. A damage-absorbing shield. Use it before every fight."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Demar Brant"}},
  {kind="train",chapter=9,lv="38",lo=38,hi=38,place="Ironforge (teleport)",title="Level 38: Mana Jade",todo={"Teleport to Ironforge and learn new ranks, including |cffffd200Conjure Mana Jade|r.","Cast it and put the |cffffd200Mana Jade|r on |cff7fd4ffShift|r + |cff7fd4ff5|r in place of the Mana Agate.","Use your |cffe2c6ff|Hwfw:13|hHearthstone|h|r to get straight back to Farholde Keep. Start saving gold: your mount costs a lot at level 40."},done="your Mana Jade is on |cff7fd4ffShift|r + |cff7fd4ff5|r.",bars={head="Action bar",rows={{id="conjuregem2",where="Right bar, button |cffffd2006|r |cff9a9a9acounting from the top|r",replaces="Conjure Mana Agate"},{id="managem2",where="|cff7fd4ffShift|r + |cff7fd4ff5|r |cff9a9a9abottom left bar|r",replaces="Mana Agate"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 36–38: |cffffd200Frost Channeling|r, 3 times. Frost spells cost less mana."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Mana Jade","Mana Jade"}},
  {kind="train",chapter=9,lv="40",lo=40,hi=40,place="Trainer + Dun Morogh",title="Level 40: your mount!",todo={"Learn riding and buy a |cffffd200mechanostrider|r (gnome mount) at |cffffd200Steelgrill's Depot|r in Dun Morogh. Right-click the mount item to learn it, then drag it from your |cffe2c6ff|Hwfw:26|hspellbook|h|r to the right bar.","At the |cffe2c6ff|Hwfw:29|htrainer|h|r, learn |cffffd200Frostfire Bolt|r, |cffffd200Teleport: Dalaran|r, the |cffffd200Portals|r to Stormwind and Ironforge, and a new |cffffd200Conjure Water|r (Mineral Water).","|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Ice Barrier|r, a shield that absorbs damage. Use it before every fight."},done="you're riding your mechanostrider, Ice Barrier is on |cff7fd4ffShift|r + |cff7fd4ff4|r and your new water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r.",bars={head="Action bar",rows={{id="mount",where="Right bar, button |cffffd20012|r |cff9a9a9acounting from the top|r"},{id="frostfire",where="|cff7fd4ffShift|r + |cff7fd4ff0|r |cff9a9a9abottom left bar|r"},{id="icebarrier",where="|cff7fd4ffShift|r + |cff7fd4ff4|r |cff9a9a9abottom left bar|r"},{id="water5",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Spring Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 40: |cffffd200Ice Barrier|r, once. A damage-absorbing shield. Use it before every fight."},pins={{zone="Dun Morogh",x=49.4,y=48.4,label="Steelgrill's Depot (mount vendor)"}},quests={"mechanostrider","Steelgrill's Depot","Frostfire Bolt","Teleport: Dalaran","Portals","Conjure Water","Ice Barrier"}},
  {kind="quest",chapter=9,lv="40–43",lo=40,hi=43,place="Riverglades (north)",title="Riverglades: Sunnyglade and the north",todo={"Fly back to Farholde Keep. Demar Brant's |cffffd200Saving Sunnyglade|r sends you north to the village of |cffffd200Sunnyglade|r.","Keep turning in and picking up: the later quests send you further north, toward |cffffd200Twilight's Shroud|r.","Pick up the quests for the |cffe2c6ff|Hwfw:6|hdungeon|h|r |cffffd200Krol'dok Stronghold|r (next step) as they appear.","|cffffd200Powderfuse Port|r, a neutral goblin port on the east coast, has a bank, an |cffe2c6ff|Hwfw:2|hauction house|h|r and the boat to Tanaris. Move on at about level 43."},done="you're level 43 and have handed in |cffffd200Saving Sunnyglade|r.",stuck="Fight the enemies around Sunnyglade until you are.",talents={"Level 40: |cffffd200Ice Barrier|r, once. A damage-absorbing shield. Use it before every fight.","Level 41: |cffffd200Precision|r, once more (3 of 3).","Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Saving Sunnyglade","Sunnyglade","Twilight's Shroud","Krol'dok Stronghold","Powderfuse Port"}},
  {kind="dungeon",chapter=9,lv="41–45",lo=41,hi=45,place="Riverglades",title="Dungeon: Krol'dok Stronghold (optional)",todo={"A new 5-player |cffe2c6ff|Hwfw:6|hdungeon|h|r for levels 40–45, with six bosses. The entrance is in the hills north of Sunnyglade (with TomTom: |cff7fd4ff/way 37.5 37.5|r).","Its quests are a chain of about ten that starts in Farholde Keep. Do the parts you can do alone first.","Find a group with the Looking For Group tool or ask in chat (\"LFG Krol'dok\")."},done="your group has beaten the last boss, or you've decided to skip it.",tip="Most |cffe2c6ff|Hwfw:6|hdungeon|h|r |cffe2c6ff|Hwfw:31|hXP|h|r in Forever comes from quests, so collect them before you go in.",talents={"Level 41: |cffffd200Precision|r, once more (3 of 3).","Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."}},
  {kind="train",chapter=9,lv="42",lo=42,hi=42,place="Ironforge (teleport)",title="Level 42: better food and Arcane talents",todo={"Learn new ranks, including a new |cffe2c6ff|Hwfw:22|hrank|h|r of |cffffd200Conjure Food|r (Conjured Sourdough). Put it on |cff7fd4ffAlt|r + |cff7fd4ff2|r.","|cffe2c6ff|Hwfw:27|hTalent|h|r: |cffffd200Winter's Chill|r (Frost tab). The Talents tab shows which one to pick each level.","Optional mage quest: |cffffd200Garon Wendell|r in the Stormwind Mage Quarter gives |cffffd200A Lesson in Literacy|r for the |cffffd200Personal |cffe2c6ff|Hwfw:26|hSpellbook|h|r|r. You need a Pristine Owlbeast Quill (owlbeasts in the Hinterlands), 5 Zukk'ash Resin (Feralas) and 8 Farraki Papyrus (zombies inside Zul'Farrak)."},done="the new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r.",bars={head="Action bar",rows={{id="food5",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Pumpernickel"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Food","Winter's Chill","Garon Wendell","A Lesson in Literacy","Personal Spellbook"}},
  {kind="travel",chapter=10,lv="43",lo=43,hi=43,place="Riverglades > Tanaris",title="Travel to Tanaris",todo={"Ride to |cffffd200Powderfuse Port|r on the Riverglades' east coast and take the boat to |cffffd200Steamwheedle Port|r in Tanaris, a desert in Kalimdor.","Follow the road west to |cffffd200Gadgetzan|r, the goblin town. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r and make the |cffe2c6ff|Hwfw:15|hinn|h|r your home.","Gadgetzan is neutral: its guards attack anyone who starts a fight in town."},done="Gadgetzan is your home and you've unlocked its |cffe2c6ff|Hwfw:10|hflight path|h|r.",talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Tanaris",x=67.5,y=23,label="Steamwheedle Port (boat)"},{zone="Tanaris",x=51,y=28,label="Gadgetzan"}},quests={"Powderfuse Port","Steamwheedle Port","Gadgetzan"}},
  {kind="quest",chapter=10,lv="43–46",lo=43,hi=46,place="Gadgetzan, Tanaris",title="Tanaris",todo={"Take every quest in Gadgetzan. |cffffd200Wastewander Justice|r and |cffffd200Water Pouch Bounty|r send you to the bandit camps east of town.","|cffffd200Noxious Lair Investigation|r from Alchemist Pestlezugg: giant insects at the Noxious Lair, south-west of town.","Steamwheedle Port has pirate quests (|cffffd200Southsea Shakedown|r, |cffffd200Pirate Hats Ahoy!|r) for the pirates at |cffffd200Lost Rigger Cove|r on the east coast.","Gadgetzan also has quests for |cffffd200Zul'Farrak|r, the |cffe2c6ff|Hwfw:6|hdungeon|h|r in the north-west. Move on at about level 46."},done="you're level 46 and have handed in |cffffd200Wastewander Justice|r and |cffffd200Water Pouch Bounty|r.",stuck="Fight the Wastewander bandits east of Gadgetzan until you are.",tip="Bandits run away at low health and come back with friends. Frost Nova them before they get away.",talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Tanaris",x=51,y=28,label="Gadgetzan"},{zone="Tanaris",x=63,y=30,label="Wastewander bandit camps"},{zone="Tanaris",x=35,y=45,label="Noxious Lair (giant insects)"},{zone="Tanaris",x=72,y=46,label="Lost Rigger Cove (pirates)"},{zone="Tanaris",x=39,y=20,label="Zul'Farrak"}},quests={"Wastewander Justice","Water Pouch Bounty","Noxious Lair Investigation","Southsea Shakedown","Pirate Hats Ahoy!","Lost Rigger Cove","Zul'Farrak"}},
  {kind="train",chapter=10,lv="44",lo=44,hi=44,place="Ironforge (teleport)",title="Level 44: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r.","Hearth back to Gadgetzan."},done="you've learned every new |cffe2c6ff|Hwfw:22|hrank|h|r your |cffe2c6ff|Hwfw:29|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}}},
  {kind="train",chapter=10,lv="46",lo=46,hi=46,place="Ironforge (teleport)",title="Level 46: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r.","Then travel on to Feralas (next step). Teleport: Darnassus and the flight to Feathermoon is a quick way there once you've been to Feathermoon."},done="you've learned every new |cffe2c6ff|Hwfw:22|hrank|h|r your |cffe2c6ff|Hwfw:29|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}}},
  {kind="dungeon",chapter=10,lv="44–48",lo=44,hi=48,place="Tanaris",title="Dungeon: Zul'Farrak (optional)",todo={"A troll city in the north-west of Tanaris, for levels 44–48. Lots of quests from Gadgetzan.","Good ones: |cffffd200Divino-matic Rod|r (Chief Engineer Bilgewhizzle) and |cffffd200Troll Temper|r (Trenton Lighthammer).","Find a group with the Looking For Group tool or ask in chat (\"LFG ZF\")."},done="your group has finished, or you've decided to skip it.",talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit.","Level 47–48: |cffffd200Arctic Reach|r, 2 times. Longer range for Frostbolt, Ice Lance and Blizzard."},pins={{zone="Tanaris",x=39,y=20,label="Zul'Farrak"},{zone="Tanaris",x=51,y=28,label="Gadgetzan"}},quests={"Divino-matic Rod","Troll Temper"}},
  {kind="travel",chapter=10,lv="46",lo=46,hi=46,place="Tanaris > Feralas",title="Travel to Feralas",todo={"From Gadgetzan, ride north into |cffffd200Thousand Needles|r. Cross the white salt flats and keep heading west along the canyon road. (Freewind Post, up on the cliffs, is Horde.)","The road leads to |cffffd200Thalanaar|r, a night elf outpost at the east edge of Feralas. Unlock its |cffe2c6ff|Hwfw:10|hflight path|h|r.","Ride west through the jungle to the coast. |cffffd200Feathermoon Stronghold|r is on an island: take the ferry from the small dock on the shore.","Unlock the Feathermoon |cffe2c6ff|Hwfw:10|hflight path|h|r and make the |cffe2c6ff|Hwfw:15|hinn|h|r your home."},done="Feathermoon Stronghold is your home and you've unlocked the Thalanaar and Feathermoon flight paths.",talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit."},pins={{zone="Thousand Needles",x=78,y=77,label="Shimmering Flats"},{zone="Feralas",x=89.5,y=46,label="Thalanaar"},{zone="Feralas",x=43.5,y=43,label="Ferry dock to Feathermoon"},{zone="Feralas",x=30.5,y=43.5,label="Feathermoon Stronghold"}},quests={"Thousand Needles","Thalanaar","Feathermoon Stronghold"}},
  {kind="quest",chapter=10,lv="46–48",lo=46,hi=48,place="Feathermoon, Feralas",title="Feralas",todo={"Take every quest in Feathermoon Stronghold, like |cffffd200The Mark of Quality|r from Pratt McGrubben (yeti hides) and the |cffffd200Rise of the Silithid|r chain.","Near the ferry dock, |cffffd200Zorbin Fandazzle|r gives |cffffd200Zapped Giants|r: use his gadget on the giants that walk along the coast.","|cffffd200Dire Maul|r, the ruined city in the middle of Feralas, is a |cffe2c6ff|Hwfw:6|hdungeon|h|r for levels 55–60. Come back much later.","Move on at about level 48."},done="you're level 48 and have handed in |cffffd200Zapped Giants|r and |cffffd200The Mark of Quality|r.",stuck="Fight the yetis in the hills or the giants on the coast until you are.",talents={"Level 42–46: |cffffd200Winter's Chill|r, 5 times. Frostbolt and empowered Ice Lance sometimes make the enemy easier to crit.","Level 47–48: |cffffd200Arctic Reach|r, 2 times. Longer range for Frostbolt, Ice Lance and Blizzard."},pins={{zone="Feralas",x=30.5,y=43.5,label="Feathermoon Stronghold"},{zone="Feralas",x=43.5,y=43,label="Ferry dock"},{zone="Feralas",x=59,y=44,label="Dire Maul (for later)"}},quests={"The Mark of Quality","Rise of the Silithid","Zorbin Fandazzle","Zapped Giants","Dire Maul"}},
  {kind="quest",chapter=10,lv="47–50",lo=47,hi=50,place="Aerie Peak, Hinterlands",title="The Hinterlands",todo={"Teleport to Ironforge, fly to |cffffd200Southshore|r, then ride north-east into |cffffd200The Hinterlands|r. |cffffd200Aerie Peak|r, the Wildhammer dwarf town, is right at the entrance.","Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r and make the |cffe2c6ff|Hwfw:15|hinn|h|r your home.","Take every quest: |cffffd200Skulk Rock Clean-up|r (oozes at Skulk Rock), |cffffd200Troll Necklace Bounty|r (necklaces from any Witherbark troll) and Gryphon Master Talonaxe's chain, starting with |cffffd200Witherbark Cages|r.","Run out of quests? |cffffd200Searing Gorge|r (town: Thorium Point) is another |cffe2c6ff|Hwfw:32|hzone|h|r for this level. Move on at level 50."},done="you're level 50 and have handed in |cffffd200Skulk Rock Clean-up|r and |cffffd200Troll Necklace Bounty|r.",stuck="Fight Witherbark trolls (their necklaces count for the bounty) until you are.",tip="WoW Forever adds a new |cffe2c6ff|Hwfw:6|hdungeon|h|r for these levels: |cffffd200Alcaz Prison|r (about 48–53). Look for it in the Looking For Group tool.",talents={"Level 47–48: |cffffd200Arctic Reach|r, 2 times. Longer range for Frostbolt, Ice Lance and Blizzard.","Level 49–50: |cffffd200Permafrost|r, 2 times. Your slows last longer and are stronger."},pins={{zone="The Hinterlands",x=14,y=46,label="Aerie Peak"},{zone="The Hinterlands",x=55,y=42,label="Skulk Rock (oozes)"},{zone="The Hinterlands",x=63,y=73,label="Jintha'Alor (trolls)"}},quests={"Southshore","The Hinterlands","Aerie Peak","Skulk Rock Clean-up","Troll Necklace Bounty","Witherbark Cages","Searing Gorge"}},
  {kind="train",chapter=10,lv="48",lo=48,hi=48,place="Ironforge (teleport)",title="Level 48: Mana Citrine",todo={"Learn new ranks, including |cffffd200Conjure Mana Citrine|r.","Put the new gem on |cff7fd4ffShift|r + |cff7fd4ff5|r. Hearth back to Aerie Peak."},done="your Mana Citrine is on |cff7fd4ffShift|r + |cff7fd4ff5|r.",bars={head="Action bar",rows={{id="conjuregem3",where="Right bar, button |cffffd2006|r |cff9a9a9acounting from the top|r",replaces="Conjure Mana Jade"},{id="managem3",where="|cff7fd4ffShift|r + |cff7fd4ff5|r |cff9a9a9abottom left bar|r",replaces="Mana Jade"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 47–48: |cffffd200Arctic Reach|r, 2 times. Longer range for Frostbolt, Ice Lance and Blizzard."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Mana Citrine"}},
  {kind="quest",chapter=11,lv="49–52",lo=49,hi=52,place="Marshal's Refuge, Un'Goro",title="Un'Goro Crater",todo={"Fly to Gadgetzan and ride west out of Tanaris. The road goes down a long ramp into |cffffd200Un'Goro Crater|r, a jungle full of dinosaurs.","Follow the crater's edge north to |cffffd200Marshal's Refuge|r, a camp under the northern cliffs. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","Take every quest. |cffffd200Crystals of Power|r from J.D. Collie: grab the red, green, blue and yellow crystals lying around the whole crater. Karna Remtravel's |cffffd200Chasing A-Me 01|r sends you to walk a lost robot home.","Watch out for |cffffd200Devilsaurs|r: huge dinosaurs that walk around and hit very hard. Stay out of their way. Move on at level 52."},done="you're level 52 and have handed in |cffffd200Crystals of Power|r and |cffffd200Chasing A-Me 01|r.",stuck="Fight the raptors and stegodons near Marshal's Refuge until you are.",tip="Devilsaurs walk the open ground and see you from far away. If one comes your way, get out of its path; if it reaches you, Frost Nova, Blink away and run.",talents={"Level 49–50: |cffffd200Permafrost|r, 2 times. Your slows last longer and are stronger.","Level 51–52: |cffffd200Improved Blizzard|r, 2 more times (3 of 3)."},pins={{zone="Un'Goro Crater",x=43.5,y=8.5,label="Marshal's Refuge"},{zone="Un'Goro Crater",x=50,y=48,label="Fire Plume Ridge (volcano)"},{zone="Un'Goro Crater",x=70,y=75,label="Entrance from Tanaris"}},quests={"Un'Goro Crater","Marshal's Refuge","Crystals of Power","Chasing A-Me 01","Devilsaurs"}},
  {kind="train",chapter=11,lv="50",lo=50,hi=50,place="Ironforge (teleport)",title="Level 50: Sparkling Water",todo={"Learn new ranks, including a new |cffe2c6ff|Hwfw:22|hrank|h|r of |cffffd200Conjure Water|r (Conjured Sparkling Water). Put it on |cff7fd4ffAlt|r + |cff7fd4ff1|r.","Learn |cffffd200Portal: Darnassus|r too. Other players often pay a little gold for a portal.","Optional mage chain: the |cffe2c6ff|Hwfw:29|htrainer|h|r gives |cffffd200Magecraft|r. It sends you to Archmage Xylem in Azshara and ends in the Sunken Temple |cffe2c6ff|Hwfw:6|hdungeon|h|r (group needed). Rewards: Glacial Spike, Arcane Crystal Pendant and Fire Ruby."},done="the new water is on |cff7fd4ffAlt|r + |cff7fd4ff1|r.",bars={head="Action bar",rows={{id="water6",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Mineral Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 49–50: |cffffd200Permafrost|r, 2 times. Your slows last longer and are stronger."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Water","Portal: Darnassus","Magecraft"}},
  {kind="train",chapter=11,lv="52",lo=52,hi=52,place="Ironforge (teleport)",title="Level 52: Sweet Rolls",todo={"Learn new ranks, including a new |cffe2c6ff|Hwfw:22|hrank|h|r of |cffffd200Conjure Food|r (Conjured Sweet Roll). Put it on |cff7fd4ffAlt|r + |cff7fd4ff2|r."},done="the new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r.",bars={head="Action bar",rows={{id="food6",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Sourdough"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 51–52: |cffffd200Improved Blizzard|r, 2 more times (3 of 3)."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Food"}},
  {kind="quest",chapter=11,lv="52–54",lo=52,hi=54,place="Felwood",title="Felwood",todo={"Get to |cffffd200Astranaar|r in Ashenvale (no |cffe2c6ff|Hwfw:10|hflight path|h|r there? Take the boat to Auberdine and ride south through Darkshore into Ashenvale), then follow the road north into |cffffd200Felwood|r, a forest poisoned by demons.","In the south, stop at the |cffffd200Emerald Sanctuary|r camp. |cffffd200Forces of Jaedenar|r from Greta Mosshoof sends you after the demon worshippers at Jaedenar, west of the road.","Follow the road north to |cffffd200Talonbranch Glade|r. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r and take its quests.","Near the north end, Nafien gives |cffffd200Deadwood of the North|r: killing the Deadwood furbolgs makes the Timbermaw furbolgs like you, so they let you walk through their tunnel to Winterspring later. Move on at level 54."},done="you're level 54 and have handed in |cffffd200Forces of Jaedenar|r and |cffffd200Deadwood of the North|r.",stuck="Fight Deadwood furbolgs in northern Felwood until you are. It also makes the Timbermaw like you.",talents={"Level 51–52: |cffffd200Improved Blizzard|r, 2 more times (3 of 3).","Level 53: |cffffd200Frost Warding|r, once. Ice Armor gives more armor.","Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect."},pins={{zone="Felwood",x=51,y=82,label="Emerald Sanctuary"},{zone="Felwood",x=37,y=60,label="Jaedenar (Shadow Council)"},{zone="Felwood",x=62.5,y=24.5,label="Talonbranch Glade"},{zone="Felwood",x=64.5,y=8,label="Timbermaw Hold (tunnel to Winterspring)"}},quests={"Astranaar","Felwood","Emerald Sanctuary","Forces of Jaedenar","Talonbranch Glade","Deadwood of the North"}},
  {kind="quest",chapter=11,lv="54–56",lo=54,hi=56,place="Morgan's Vigil, Burning Steppes",title="Burning Steppes",todo={"Fly to Lakeshire and ride north into |cffffd200Burning Steppes|r, a scorched land of orcs and dragons. |cffffd200Morgan's Vigil|r, the Alliance camp, is just over the border. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","Take every quest. |cffffd200Dragonkin Menace|r from Helendis Riverhorn (black dragonkin in the north) starts a very long chain that matters much later at 60.","The Blackrock orcs all over the |cffe2c6ff|Hwfw:32|hzone|h|r are targets for several quests.","|cffffd200Blackrock Depths|r, a huge |cffe2c6ff|Hwfw:6|hdungeon|h|r inside Blackrock Mountain (west), is great from 52 to 60. Go with a group. Move on at level 56."},done="you're level 56 and have handed in |cffffd200Dragonkin Menace|r.",stuck="Fight the Blackrock orcs around the |cffe2c6ff|Hwfw:32|hzone|h|r until you are.",tip="WoW Forever adds new dungeons for these levels too: |cffffd200Blackmaw Hold|r (55–60) and |cffffd200Shaper's Terrace|r (58–60). Look for them in the Looking For Group tool.",talents={"Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect."},pins={{zone="Burning Steppes",x=84,y=68,label="Morgan's Vigil"},{zone="Burning Steppes",x=65,y=24,label="Flame Crest (black dragons)"},{zone="Burning Steppes",x=28,y=36,label="Blackrock Mountain"}},quests={"Burning Steppes","Morgan's Vigil","Dragonkin Menace","Blackrock Depths"}},
  {kind="train",chapter=11,lv="54",lo=54,hi=54,place="Ironforge (teleport)",title="Level 54: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r.","|cffe2c6ff|Hwfw:27|hTalent|h|r: Frost is finished. Your last points go into the |cffffd200Arcane|r tab, starting with |cffffd200Arcane Resilience|r.","Hearth back and carry on."},done="you've learned every new |cffe2c6ff|Hwfw:22|hrank|h|r your |cffe2c6ff|Hwfw:29|htrainer|h|r offers and your |cffe2c6ff|Hwfw:27|htalent|h|r point is in Arcane Resilience.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}},quests={"Arcane","Arcane Resilience"}},
  {kind="quest",chapter=11,lv="55–57",lo=55,hi=57,place="Chillwind Camp, Western Plaguelands",title="Western Plaguelands",todo={"Fly to Southshore and ride north through the Alterac Mountains into |cffffd200Western Plaguelands|r. |cffffd200Chillwind Camp|r is just inside, in the south. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","|cffffd200The Scourge Cauldrons|r chain: undead lords guard four cauldrons that poison the land, at Felstone Field, Dalson's Tears, the Writhing Haunt and Gahrron's Withering. Kill each lord and use his key on his cauldron.","|cffffd200Andorhal|r, the ruined city in the middle, has more undead quests.","Move on at level 57."},done="you're level 57 and all four cauldrons are done.",stuck="Fight the undead around Andorhal until you are.",tip="Undead can't be Polymorphed. Use Frost Nova and step back instead.",talents={"Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect.","Level 57–58: |cffffd200Wand Specialization|r, 2 times. Your wand hits harder."},pins={{zone="Western Plaguelands",x=43,y=84,label="Chillwind Camp"},{zone="Western Plaguelands",x=37,y=57,label="Felstone Field"},{zone="Western Plaguelands",x=46,y=52,label="Dalson's Tears"},{zone="Western Plaguelands",x=53,y=66,label="Writhing Haunt"},{zone="Western Plaguelands",x=62,y=58,label="Gahrron's Withering"},{zone="Western Plaguelands",x=43,y=70,label="Andorhal"}},quests={"Western Plaguelands","Chillwind Camp","The Scourge Cauldrons","Andorhal"}},
  {kind="train",chapter=11,lv="56",lo=56,hi=56,place="Ironforge (teleport)",title="Level 56: new ranks",todo={"Teleport to Ironforge and learn every new |cffe2c6ff|Hwfw:22|hrank|h|r.","Fly back to Chillwind Camp and carry on."},done="you've learned every new |cffe2c6ff|Hwfw:22|hrank|h|r your |cffe2c6ff|Hwfw:29|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"}}},
  {kind="quest",chapter=11,lv="56–58",lo=56,hi=58,place="Light's Hope, Eastern Plaguelands",title="Eastern Plaguelands",todo={"Ride east into |cffffd200Eastern Plaguelands|r and follow the road to |cffffd200Light's Hope Chapel|r on the far east side. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r.","The |cffffd200Argent Dawn|r at Light's Hope fight the undead. Their quests give good |cffe2c6ff|Hwfw:31|hXP|h|r and reputation.","In the ruined village of |cffffd200Darrowshire|r (south-west), talk to the little ghost girl |cffffd200Pamela Redpath|r. Her quests tell one of the saddest stories in WoW.","In a small house by the river in the far west, |cffffd200Tirion Fordring|r starts the famous |cffffd200Redemption|r chain. Move on at level 58."},done="you're level 58.",stuck="Fight the undead near Light's Hope Chapel until you are.",talents={"Level 54–56: |cffffd200Arcane Resilience (Arcane tab)|r, 3 times. Switch to the Arcane tab now. More armor from your Intellect.","Level 57–58: |cffffd200Wand Specialization|r, 2 times. Your wand hits harder."},pins={{zone="Eastern Plaguelands",x=81.5,y=59,label="Light's Hope Chapel"},{zone="Eastern Plaguelands",x=36,y=90,label="Darrowshire"},{zone="Eastern Plaguelands",x=7,y=43,label="Tirion Fordring's house"},{zone="Eastern Plaguelands",x=27,y=11,label="Stratholme"}},quests={"Eastern Plaguelands","Light's Hope Chapel","Argent Dawn","Darrowshire","Pamela Redpath","Tirion Fordring","Redemption"}},
  {kind="train",chapter=11,lv="58",lo=58,hi=58,place="Ironforge (teleport)",title="Level 58: Mana Ruby",todo={"Learn new ranks, including |cffffd200Conjure Mana Ruby|r, your best mana gem."},done="your Mana Ruby is on |cff7fd4ffShift|r + |cff7fd4ff5|r.",bars={head="Action bar",rows={{id="conjuregem4",where="Right bar, button |cffffd2006|r |cff9a9a9acounting from the top|r",replaces="Conjure Mana Citrine"},{id="managem4",where="|cff7fd4ffShift|r + |cff7fd4ff5|r |cff9a9a9abottom left bar|r",replaces="Mana Citrine"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 57–58: |cffffd200Wand Specialization|r, 2 times. Your wand hits harder."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Mana Ruby"}},
  {kind="quest",chapter=11,lv="58–60",lo=58,hi=60,place="Everlook, Winterspring",title="Winterspring",todo={"Fly to Talonbranch Glade in Felwood and walk north through the |cffffd200Timbermaw Hold|r tunnel. It comes out in |cffffd200Winterspring|r, a snowy valley.","At the hot springs, talk to |cffffd200Donova Snowden|r: her quests are about the Winterfall furbolgs.","Follow the road east to |cffffd200Everlook|r, a goblin town. Unlock the |cffe2c6ff|Hwfw:10|hflight path|h|r, make it your home and take every quest, like |cffffd200Are We There, Yeti?|r from Legacki.","For the last bars of |cffe2c6ff|Hwfw:31|hXP|h|r, run end-game dungeons with groups: Blackrock Depths, Lower Blackrock Spire, Dire Maul, Stratholme and Scholomance."},done="you're level 60!",stuck="Fight Winterfall furbolgs, or run Blackrock Depths with a group, until you are.",talents={"Level 57–58: |cffffd200Wand Specialization|r, 2 times. Your wand hits harder.","Level 59–60: |cffffd200Arcane Subtlety|r, 2 times. Enemies resist your spells less. That's all 51 points."},pins={{zone="Felwood",x=64.5,y=8,label="Timbermaw Hold (tunnel)"},{zone="Winterspring",x=61,y=38.5,label="Everlook"},{zone="Winterspring",x=31,y=45,label="Donova Snowden (hot springs)"},{zone="Winterspring",x=67,y=36,label="Winterfall Village (furbolgs)"}},quests={"Timbermaw Hold","Winterspring","Donova Snowden","Everlook","Are We There, Yeti?"}},
  {kind="train",chapter=11,lv="60",lo=60,hi=60,place="Ironforge (teleport)",title="Level 60: the last ranks",todo={"Learn the last ranks, including a new |cffffd200Conjure Food|r (Conjured Cinnamon Rolls). Put it on |cff7fd4ffAlt|r + |cff7fd4ff2|r.","Spend your last |cffe2c6ff|Hwfw:27|htalent|h|r point on |cffffd200Arcane Subtlety|r. That's all 51.","The best water, |cffffd200Conjured Crystal Water|r, doesn't come from the |cffe2c6ff|Hwfw:29|htrainer|h|r: it's the reward for |cffffd200Arcane Refreshment|r, a quest from Lorekeeper Lydros in Dire Maul (a group |cffe2c6ff|Hwfw:6|hdungeon|h|r)."},done="the new food is on |cff7fd4ffAlt|r + |cff7fd4ff2|r and all 51 |cffe2c6ff|Hwfw:27|htalent|h|r points are spent.",bars={head="Action bar",rows={{id="food7",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Conjured Sweet Roll"},{id="water7",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Conjured Sparkling Water"}},notes={"Water, food and gems are items: they show up in your bags after you cast the Conjure spell. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or eat up the old ones.","New ranks of spells you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 59–60: |cffffd200Arcane Subtlety|r, 2 times. Enemies resist your spells less. That's all 51 points."},pins={{zone="Ironforge",x=26.5,y=8.5,label="Mage trainers (Hall of Mysteries)"},{zone="Ironforge",x=55.5,y=47.7,label="Gryphon master: you land here"}},quests={"Conjure Food","Arcane Subtlety","Conjured Crystal Water","Arcane Refreshment"}},
  {kind="done",chapter=11,lv="60",lo=60,hi=60,place="Mount Hyjal",title="You made it to 60!",todo={"Visit |cffffd200Mount Hyjal|r, a new level 60 |cffe2c6ff|Hwfw:32|hzone|h|r reached through Winterspring.","From here on, it's about gear, dungeons and raids. Congratulations!"},talents={"Level 59–60: |cffffd200Arcane Subtlety|r, 2 times. Enemies resist your spells less. That's all 51 points."},quests={"Mount Hyjal"}},
}
